import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AttendanceStatus {
  PRESENT = 'มา',
  LEAVE = 'ลา',
  ABSENT = 'ขาด',
  LATE = 'สาย'
}

export interface Student {
  id: string;
  studentId: string;
  fullName: string;
  grade: string;
  room: string;
  number: number;
}

export interface Subject {
  id: string;
  code: string;
  name: string;
  grade: string;
  semester: string;
  year: string;
  hours: number;
  numCollectScores: number;
  collectPercent: number;
  midtermPercent: number;
  finalPercent: number;
}

export interface AttendanceRecord {
  studentId: string;
  status: AttendanceStatus;
  note?: string;
}

export interface AttendanceSession {
  id: string;
  subjectCode: string;
  date: string;
  periods: number;
  records: AttendanceRecord[];
}

export interface Score {
  studentId: string;
  collectScores: Record<number, number>;
  midterm: number;
  final: number;
  totalScore: number;
  grade: string;
}

export interface SubjectScoreSheet {
  subjectCode: string;
  scores: Score[];
  assignmentNames: Record<number, { name: string; maxScore: number }>;
}

export interface TelegramConfig {
  subjectCode: string;
  botName: string;
  botToken: string;
  chatId: string;
}

import { Student, Subject, AttendanceSession, SubjectScoreSheet, TelegramConfig } from '../types';

const KEYS = {
  STUDENTS: 'scm_students',
  SUBJECTS: 'scm_subjects',
  ATTENDANCE: 'scm_attendance',
  SCORES: 'scm_scores',
  TELEGRAM: 'scm_telegram',
  ENROLLMENT: 'scm_enrollment'
};

export const storageService = {
  getStudents: (): Student[] => JSON.parse(localStorage.getItem(KEYS.STUDENTS) || '[]'),
  saveStudents: (data: Student[]) => localStorage.setItem(KEYS.STUDENTS, JSON.stringify(data)),

  getSubjects: (): Subject[] => JSON.parse(localStorage.getItem(KEYS.SUBJECTS) || '[]'),
  saveSubjects: (data: Subject[]) => localStorage.setItem(KEYS.SUBJECTS, JSON.stringify(data)),

  getAttendance: (): AttendanceSession[] => JSON.parse(localStorage.getItem(KEYS.ATTENDANCE) || '[]'),
  saveAttendance: (data: AttendanceSession[]) => localStorage.setItem(KEYS.ATTENDANCE, JSON.stringify(data)),

  getScores: (): SubjectScoreSheet[] => JSON.parse(localStorage.getItem(KEYS.SCORES) || '[]'),
  saveScores: (data: SubjectScoreSheet[]) => localStorage.setItem(KEYS.SCORES, JSON.stringify(data)),

  getTelegram: (): TelegramConfig[] => JSON.parse(localStorage.getItem(KEYS.TELEGRAM) || '[]'),
  saveTelegram: (data: TelegramConfig[]) => localStorage.setItem(KEYS.TELEGRAM, JSON.stringify(data)),

  getEnrollment: (): Record<string, string[]> => JSON.parse(localStorage.getItem(KEYS.ENROLLMENT) || '{}'),
  saveEnrollment: (data: Record<string, string[]>) => localStorage.setItem(KEYS.ENROLLMENT, JSON.stringify(data))
};

import { GoogleGenAI } from "@google/genai";
import { Score, Student } from "../types";

export const geminiService = {
  analyzePerformance: async (students: Student[], scores: Score[], subjectName: string) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const performanceContext = scores.map(s => {
      const student = students.find(st => st.studentId === s.studentId);
      return `${student?.fullName}: Score ${s.totalScore}, Grade ${s.grade}`;
    }).join('\n');

    const prompt = `
      You are an expert pedagogical analyst. Analyze the following student performance data for the subject "${subjectName}".
      Provide a brief summary (max 200 words) in Thai language.
      Identify:
      1. Overall class performance (Average).
      2. Students who might need extra help (Score < 50).
      3. Students who are excelling.
      4. One actionable advice for the teacher to improve learning outcomes.

      Data:
      ${performanceContext}
    `;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });
      return response.text;
    } catch (error) {
      console.error("AI Analysis failed:", error);
      return "ไม่สามารถวิเคราะห์ข้อมูลได้ในขณะนี้";
    }
  }
};

