import React, { useState } from 'react';
import { AttendanceSession } from '../types';
import { ChevronLeft, ChevronRight } from 'lucide-react';

interface CalendarViewProps {
  attendance: AttendanceSession[];
}

const CalendarView: React.FC<CalendarViewProps> = ({ attendance }) => {
  const [currentMonth, setCurrentMonth] = useState(new Date().getMonth());
  const [currentYear, setCurrentYear] = useState(new Date().getFullYear());

  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
  const firstDay = new Date(currentYear, currentMonth, 1).getDay();
  const monthNames = ["มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน", "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"];

  const attendanceDates = attendance.map(a => a.date);

  const prevMonth = () => {
    if (currentMonth === 0) { setCurrentMonth(11); setCurrentYear(currentYear - 1); }
    else setCurrentMonth(currentMonth - 1);
  };

  const nextMonth = () => {
    if (currentMonth === 11) { setCurrentMonth(0); setCurrentYear(currentYear + 1); }
    else setCurrentMonth(currentMonth + 1);
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-3xl border border-gray-100">
        <div className="flex items-center justify-between mb-8">
          <h2 className="text-xl font-bold text-gray-800">{monthNames[currentMonth]} {currentYear + 543}</h2>
          <div className="flex gap-2">
            <button onClick={prevMonth} className="p-2 hover:bg-gray-50 rounded-xl transition-colors"><ChevronLeft /></button>
            <button onClick={nextMonth} className="p-2 hover:bg-gray-50 rounded-xl transition-colors"><ChevronRight /></button>
          </div>
        </div>

        <div className="grid grid-cols-7 gap-2">
          {['อา', 'จ', 'อ', 'พ', 'พฤ', 'ศ', 'ส'].map(d => (
            <div key={d} className="text-center text-xs font-bold text-gray-400 py-4">{d}</div>
          ))}

          {Array(firstDay).fill(null).map((_, i) => (
            <div key={`empty-${i}`} className="h-24 sm:h-32"></div>
          ))}

          {Array(daysInMonth).fill(null).map((_, i) => {
            const day = i + 1;
            const dateStr = `${currentYear}-${String(currentMonth + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
            const sessions = attendance.filter(a => a.date === dateStr);
            const hasAttendance = sessions.length > 0;

            return (
              <div key={day} className={`h-24 sm:h-32 p-2 border rounded-2xl transition-all relative ${
                hasAttendance ? 'bg-green-50/50 border-green-100' : 'bg-white border-gray-50'
              }`}>
                <span className={`text-sm font-bold ${hasAttendance ? 'text-green-600' : 'text-gray-400'}`}>{day}</span>
                {hasAttendance && (
                  <div className="mt-2 space-y-1 overflow-hidden">
                    {sessions.map(s => (
                      <div key={s.id} className="text-[10px] bg-green-500 text-white p-1 rounded-md truncate font-bold">
                        {s.subjectCode}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

