import React, { useState } from 'react';
import { Plus, Trash2, Edit2, User, Search, FileText, Check, AlertCircle, X } from 'lucide-react';
import { Student } from '../types';
import { storageService } from '../services/storageService';

interface StudentsProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
}

const Students: React.FC<StudentsProps> = ({ students, setStudents }) => {
  const [showForm, setShowForm] = useState(false);
  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [formData, setFormData] = useState<Partial<Student>>({
    studentId: '',
    fullName: '',
    grade: 'ม.1',
    room: '1',
    number: 1
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    let updated: Student[];
    if (editingId) {
      updated = students.map(s => s.id === editingId ? { ...s, ...formData } as Student : s);
    } else {
      updated = [...students, { ...formData, id: Date.now().toString() } as Student];
    }
    setStudents(updated);
    storageService.saveStudents(updated);
    setShowForm(false);
    setEditingId(null);
    setFormData({ studentId: '', fullName: '', grade: 'ม.1', room: '1', number: 1 });
  };

  const handleBulkImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.trim().split('\n');
      // Find header or data starts
      const startIdx = lines[0].toLowerCase().includes('id') || lines[0].includes('รหัส') ? 1 : 0;

      const newEntries: Student[] = lines.slice(startIdx).map((line, index) => {
        // Split by Tab (common in Excel/Table copy) or multiple spaces
        const cols = line.split(/\t/);

        // Mapping from the provided structure: id, name, class, grade, status, number
        // 1477	กฤษฎา กาละพันธ์	ม.1/1	ม.1	Active	1
        const studentId = cols[0]?.trim() || '';
        const fullName = cols[1]?.trim() || '';
        const classStr = cols[2]?.trim() || ''; // e.g. ม.1/1
        const grade = cols[3]?.trim() || 'ม.1';
        const number = parseInt(cols[5]?.trim() || '0');

        // Extract room from "ม.1/1" -> "1"
        const room = classStr.includes('/') ? classStr.split('/')[1] : '1';

        return {
          id: (Date.now() + index).toString(),
          studentId,
          fullName,
          grade,
          room,
          number
        };
      }).filter(s => s.studentId && s.fullName);

      if (newEntries.length === 0) {
        alert('ไม่พบข้อมูลที่ถูกต้อง กรุณาตรวจสอบรูปแบบข้อความ');
        return;
      }

      // Check for duplicates based on studentId
      const existingIds = new Set(students.map(s => s.studentId));
      const uniqueNewEntries = newEntries.filter(s => !existingIds.has(s.studentId));

      const updated = [...students, ...uniqueNewEntries];
      setStudents(updated);
      storageService.saveStudents(updated);

      alert(`นำเข้าสำเร็จ ${uniqueNewEntries.length} รายการ (ข้ามรายการซ้ำ ${newEntries.length - uniqueNewEntries.length} รายการ)`);
      setImportText('');
      setShowImport(false);
    } catch (err) {
      console.error(err);
      alert('เกิดข้อผิดพลาดในการนำเข้าข้อมูล กรุณาตรวจสอบรูปแบบอีกครั้ง');
    }
  };

  const handleDelete = (id: string) => {
    if (confirm('ยืนยันการลบนักเรียน?')) {
      const updated = students.filter(s => s.id !== id);
      setStudents(updated);
      storageService.saveStudents(updated);
    }
  };

  const filteredStudents = students.filter(s => 
    s.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    s.studentId.includes(searchTerm) ||
    s.grade.includes(searchTerm)
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">จัดการนักเรียน</h2>
          <p className="text-gray-500">จัดการข้อมูลพื้นฐานของนักเรียนรายบุคคล หรือนำเข้าเป็นกลุ่ม</p>
        </div>
        <div className="flex flex-wrap gap-2">
          <div className="relative flex-1 sm:flex-none">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input 
              className="pl-10 pr-4 py-2.5 bg-white border border-gray-200 rounded-xl outline-none focus:border-indigo-500 w-full sm:w-64" 
              placeholder="ค้นหาชื่อ/รหัส/ชั้น..."
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            onClick={() => { setShowImport(!showImport); setShowForm(false); }}
            className={`px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 transition-all ${
              showImport ? 'bg-gray-200 text-gray-700' : 'bg-white border border-gray-200 text-gray-600 hover:bg-gray-50'
            }`}
          >
            <FileText size={20} />
            <span className="hidden sm:inline">นำเข้าข้อมูล</span>
          </button>
          <button 
            onClick={() => { setShowForm(!showForm); setShowImport(false); }}
            className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-indigo-100"
          >
            <Plus size={20} />
            <span className="hidden sm:inline">เพิ่มนักเรียน</span>
          </button>
        </div>
      </div>

      {/* Bulk Import UI */}
      {showImport && (
        <div className="bg-white p-6 rounded-3xl border border-indigo-100 shadow-xl space-y-4 animate-in slide-in-from-top duration-300">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-bold text-indigo-900 flex items-center gap-2">
              <FileText size={20} />
              นำเข้าข้อมูลจากตาราง (Excel/TSV)
            </h3>
            <button onClick={() => setShowImport(false)} className="text-gray-400 hover:text-gray-600">
              <X size={20} />
            </button>
          </div>
          <div className="p-4 bg-indigo-50 rounded-2xl border border-indigo-100 flex items-start gap-3">
            <AlertCircle className="text-indigo-600 shrink-0 mt-0.5" size={18} />
            <p className="text-xs text-indigo-700 leading-relaxed">
              คัดลอกข้อมูลจาก Excel หรือตารางที่มีคอลัมน์ <b>[ID, ชื่อ, ห้อง/ชั้น, ชั้น, สถานะ, เลขที่]</b> มาวางในช่องด้านล่างได้เลย ระบบจะเลือกข้อมูลที่จำเป็นมาบันทึกให้อัตโนมัติ
            </p>
          </div>
          <textarea 
            className="w-full h-48 px-4 py-3 rounded-2xl border border-gray-200 font-mono text-sm focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 outline-none transition-all"
            placeholder="วางข้อมูลที่นี่..."
            value={importText}
            onChange={(e) => setImportText(e.target.value)}
          />
          <div className="flex justify-end gap-3">
            <button onClick={() => setShowImport(false)} className="px-6 py-2 text-gray-500 font-bold">ยกเลิก</button>
            <button 
              onClick={handleBulkImport}
              disabled={!importText.trim()}
              className="bg-indigo-600 text-white px-8 py-2 rounded-xl font-bold flex items-center gap-2 disabled:opacity-50"
            >
              <Check size={18} />
              ยืนยันการนำเข้า
            </button>
          </div>
        </div>
      )}

      {showForm && (
        <form onSubmit={handleSubmit} className="bg-white p-6 rounded-3xl border border-gray-100 shadow-xl space-y-4 animate-in slide-in-from-top duration-300">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            <div className="space-y-1">
              <label className="text-xs font-bold text-gray-500 uppercase">รหัสนักเรียน</label>
              <input required className="w-full px-4 py-2 rounded-xl border border-gray-200" value={formData.studentId} onChange={e => setFormData({...formData, studentId: e.target.value})} />
            </div>
            <div className="space-y-1 sm:col-span-2 lg:col-span-1">
              <label className="text-xs font-bold text-gray-500 uppercase">ชื่อ-นามสกุล</label>
              <input required className="w-full px-4 py-2 rounded-xl border border-gray-200" value={formData.fullName} onChange={e => setFormData({...formData, fullName: e.target.value})} />
            </div>
            <div className="grid grid-cols-3 gap-4">
              <div className="space-y-1">
                <label className="text-xs font-bold text-gray-500 uppercase">ชั้น</label>
                <select className="w-full px-4 py-2 rounded-xl border border-gray-200" value={formData.grade} onChange={e => setFormData({...formData, grade: e.target.value})}>
                  {['ม.1', 'ม.2', 'ม.3', 'ม.4', 'ม.5', 'ม.6'].map(g => <option key={g} value={g}>{g}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-gray-500 uppercase">ห้อง</label>
                <input required type="text" className="w-full px-4 py-2 rounded-xl border border-gray-200" value={formData.room} onChange={e => setFormData({...formData, room: e.target.value})} />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-gray-500 uppercase">เลขที่</label>
                <input required type="number" className="w-full px-4 py-2 rounded-xl border border-gray-200" value={formData.number} onChange={e => setFormData({...formData, number: parseInt(e.target.value)})} />
              </div>
            </div>
          </div>
          <div className="flex justify-end gap-3 pt-4">
            <button type="button" onClick={() => setShowForm(false)} className="px-6 py-2 text-gray-500 font-bold">ยกเลิก</button>
            <button type="submit" className="bg-indigo-600 text-white px-8 py-2 rounded-xl font-bold">บันทึก</button>
          </div>
        </form>
      )}

      <div className="bg-white rounded-3xl border border-gray-100 overflow-hidden shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-gray-50 border-b border-gray-100">
              <tr>
                <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">รหัส</th>
                <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">ชื่อ-นามสกุล</th>
                <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">ชั้น/ห้อง</th>
                <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">เลขที่</th>
                <th className="px-6 py-4 text-right text-xs font-bold text-gray-500 uppercase tracking-wider">จัดการ</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredStudents.sort((a,b) => {
                if (a.grade !== b.grade) return a.grade.localeCompare(b.grade);
                if (a.room !== b.room) return a.room.localeCompare(b.room);
                return a.number - b.number;
              }).map(student => (
                <tr key={student.id} className="hover:bg-indigo-50/30 transition-colors group">
                  <td className="px-6 py-4 text-sm font-medium text-indigo-600">{student.studentId}</td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600">
                        <User size={14} />
                      </div>
                      <span className="text-sm font-bold text-gray-900">{student.fullName}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-sm text-gray-600">{student.grade}/{student.room}</td>
                  <td className="px-6 py-4 text-sm text-gray-600 font-bold">{student.number}</td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => { setFormData(student); setEditingId(student.id); setShowForm(true); setShowImport(false); }} className="p-2 text-gray-400 hover:text-indigo-600"><Edit2 size={16} /></button>
                      <button onClick={() => handleDelete(student.id)} className="p-2 text-gray-400 hover:text-red-500"><Trash2 size={16} /></button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredStudents.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-6 py-20 text-center text-gray-400">
                    ไม่พบข้อมูลนักเรียน
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Students;

