  const [students, setStudents] = useState<Student[]>([]);
  const [enrollments, setEnrollments] = useState<Record<string, string[]>>({});
  const [attendance, setAttendance] = useState<AttendanceSession[]>([]);
  const [scores, setScores] = useState<SubjectScoreSheet[]>([]);
  const [telegramConfigs, setTelegramConfigs] = useState<TelegramConfig[]>([]);

  // Initialize data
  useEffect(() => {
    // Load subjects - if empty, use initialSubjects
    const storedSubjects = storageService.getSubjects();
    if (storedSubjects.length === 0) {
      setSubjects(initialSubjects);
      storageService.saveSubjects(initialSubjects);
    } else {
      setSubjects(storedSubjects);
    }

    // Load students - if empty, use initialStudents
    const storedStudents = storageService.getStudents();
    if (storedStudents.length === 0) {
      setStudents(initialStudents);
      storageService.saveStudents(initialStudents);
    } else {
