          <div className="flex justify-end gap-3">
            <button onClick={handleBulkImport} className="bg-indigo-600 text-white px-8 py-2 rounded-xl font-bold">ยืนยันนำเข้า</button>
          </div>
        </div>
      )}

      {showForm && (
        <form onSubmit={handleSubmit} className="bg-white p-6 rounded-3xl border border-gray-100 shadow-xl space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            <div className="space-y-1">
              <label className="text-xs font-bold text-gray-500 uppercase">รหัส (รองรับ 5 หลัก เช่น 01234)</label>
