import React, { useRef } from 'react';
import { Download, Upload, Trash2, ShieldCheck, AlertTriangle, FileJson, RefreshCw, RotateCcw } from 'lucide-react';
import { storageService } from '../services/storageService';
import { initialStudents } from '../initialStudents';
import { initialSubjects } from '../initialSubjects';

const BackupRestore: React.FC = () => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleExport = () => {
    const data = storageService.getAllData();
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    const date = new Date().toISOString().split('T')[0];
    const time = new Date().toLocaleTimeString('th-TH').replace(/:/g, '-');

    link.href = url;
    link.download = `smartclass_backup_${date}_${time}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const json = JSON.parse(e.target?.result as string);
        if (confirm('การนำเข้าข้อมูลจะเขียนทับข้อมูลปัจจุบันทั้งหมด ยืนยันที่จะดำเนินการต่อหรือไม่?')) {
          const success = storageService.restoreAllData(json);
          if (success) {
            alert('นำเข้าข้อมูลสำเร็จ! ระบบจะทำการรีโหลดหน้าเว็บ');
            window.location.reload();
          } else {
            alert('เกิดข้อผิดพลาดในการนำเข้าข้อมูล');
          }
        }
      } catch (err) {
        alert('ไฟล์ไม่ถูกต้อง กรุณาเลือกไฟล์ JSON ที่ได้จากการสำรองข้อมูลของระบบนี้เท่านั้น');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleClearData = () => {
    if (confirm('คำเตือน: ข้อมูลทั้งหมดจะถูกลบอย่างถาวรและไม่สามารถกู้คืนได้ ยืนยันการลบข้อมูลทั้งหมด?')) {
      storageService.clearAllData();
      alert('ล้างข้อมูลสำเร็จ!');
      window.location.reload();
    }
  };

  const handleResetToDefaults = () => {
    if (confirm('ระบบจะล้างข้อมูลปัจจุบันและแทนที่ด้วยข้อมูลเริ่มต้นใหม่ (รหัสนักเรียน 5 หลัก และปีการศึกษา 2568) ยืนยันการดำเนินการ?')) {
      storageService.clearAllData();
      storageService.saveStudents(initialStudents);
      storageService.saveSubjects(initialSubjects);
      alert('อัปเดตข้อมูลเป็นค่าเริ่มต้นสำเร็จ!');
      window.location.reload();
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom duration-500">
      <div className="bg-indigo-600 p-8 rounded-[2rem] text-white shadow-xl shadow-indigo-100 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-32 -mt-32 blur-3xl"></div>
        <div className="relative z-10">
          <h2 className="text-2xl font-bold mb-2 flex items-center gap-3">
            <ShieldCheck size={32} />
            จัดการและสำรองข้อมูล
          </h2>
          <p className="text-indigo-100">เก็บรักษาข้อมูลของคุณให้ปลอดภัยด้วยการสำรองข้อมูลเป็นประจำ</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Export Card */}
        <div className="bg-white p-8 rounded-[2rem] border border-gray-100 shadow-sm hover:border-indigo-200 transition-all flex flex-col items-center text-center">
          <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center mb-6">
            <Download size={32} />
          </div>
          <h3 className="text-xl font-bold text-gray-900 mb-2">สำรองข้อมูล (Export)</h3>
          <p className="text-gray-500 mb-8 text-sm leading-relaxed">
            ดาวน์โหลดข้อมูลทั้งหมดในระบบประกอบด้วย รายชื่อนักเรียน, รายวิชา, บันทึกการเช็คชื่อ และคะแนน เก็บไว้ในรูปแบบไฟล์ .json
          </p>
          <button 
            onClick={handleExport}
            className="w-full mt-auto bg-blue-600 text-white py-4 rounded-2xl font-bold shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all flex items-center justify-center gap-2"
          >
            <FileJson size={20} />
            ดาวน์โหลดไฟล์สำรองข้อมูล
          </button>
        </div>

        {/* Import Card */}
        <div className="bg-white p-8 rounded-[2rem] border border-gray-100 shadow-sm hover:border-purple-200 transition-all flex flex-col items-center text-center">
          <div className="w-16 h-16 bg-purple-50 text-purple-600 rounded-2xl flex items-center justify-center mb-6">
            <Upload size={32} />
          </div>
          <h3 className="text-xl font-bold text-gray-900 mb-2">นำเข้าข้อมูล (Restore)</h3>
          <p className="text-gray-500 mb-8 text-sm leading-relaxed">
            เลือกไฟล์สำรองข้อมูล (.json) เพื่อนำข้อมูลกลับเข้าสู่ระบบ ข้อมูลปัจจุบันจะถูกเขียนทับด้วยข้อมูลจากไฟล์
          </p>
          <input 
            type="file" 
            ref={fileInputRef}
            onChange={handleImport}
            accept=".json"
            className="hidden"
          />
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="w-full mt-auto bg-purple-600 text-white py-4 rounded-2xl font-bold shadow-lg shadow-purple-100 hover:bg-purple-700 transition-all flex items-center justify-center gap-2"
          >
            <RefreshCw size={20} />
            เลือกไฟล์และกู้คืนข้อมูล
          </button>
        </div>
      </div>

      {/* Sync with Defaults */}
      <div className="bg-indigo-50 p-8 rounded-[2rem] border border-indigo-100">
        <div className="flex flex-col md:flex-row items-center justify-between gap-6">
          <div className="flex items-center gap-4 text-center md:text-left">
            <div className="w-12 h-12 bg-white text-indigo-600 rounded-xl flex items-center justify-center shrink-0 shadow-sm border border-indigo-100">
              <RotateCcw size={24} />
            </div>
            <div>
              <h4 className="font-bold text-indigo-900 text-lg">อัปเดตข้อมูลเป็นค่าเริ่มต้น</h4>
              <p className="text-indigo-700 text-sm">โหลดรายชื่อนักเรียนและรายวิชาใหม่ตามระบบล่าสุด (แนะนำสำหรับการเริ่มต้นปีการศึกษา 2568)</p>
            </div>
          </div>
          <button 
            onClick={handleResetToDefaults}
            className="bg-white text-indigo-600 border-2 border-indigo-600 px-8 py-4 rounded-2xl font-bold hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center gap-2 shrink-0"
          >
            <RotateCcw size={20} />
            โหลดข้อมูลเริ่มต้นใหม่
          </button>
        </div>
      </div>

      {/* Danger Zone */}
      <div className="bg-red-50 p-8 rounded-[2rem] border border-red-100">
        <div className="flex flex-col md:flex-row items-center justify-between gap-6">
          <div className="flex items-center gap-4 text-center md:text-left">
            <div className="w-12 h-12 bg-red-100 text-red-600 rounded-xl flex items-center justify-center shrink-0">
              <AlertTriangle size={24} />
            </div>
            <div>
              <h4 className="font-bold text-red-900 text-lg">พื้นที่อันตราย</h4>
              <p className="text-red-700 text-sm">ล้างข้อมูลทั้งหมดในเครื่องเพื่อเริ่มต้นใหม่ ข้อมูลที่ถูกลบไปแล้วจะไม่สามารถกู้คืนได้</p>
            </div>
          </div>
          <button 
            onClick={handleClearData}
            className="bg-red-600 text-white px-8 py-4 rounded-2xl font-bold shadow-lg shadow-red-100 hover:bg-red-700 transition-all flex items-center justify-center gap-2 shrink-0"
          >
            <Trash2 size={20} />
            ล้างข้อมูลทั้งหมด
          </button>
        </div>
      </div>
    </div>
  );
};

export default BackupRestore;

import React, { useState, useEffect } from 'react';
import { Subject, Student } from '../types';
import { storageService } from '../services/storageService';
import { Search, CheckCircle2, Circle, Save, CheckSquare, Square, AlertCircle } from 'lucide-react';

interface EnrollmentProps {
  subjects: Subject[];
  students: Student[];
  enrollments: Record<string, string[]>;
  setEnrollments: React.Dispatch<React.SetStateAction<Record<string, string[]>>>;
}

const Enrollment: React.FC<EnrollmentProps> = ({ subjects, students, enrollments, setEnrollments }) => {
  const [selectedSubject, setSelectedSubject] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState('');
  const [localEnrollments, setLocalEnrollments] = useState<Record<string, string[]>>({});
  const [isDirty, setIsDirty] = useState(false);

  // Sync local state when global enrollments change (e.g. on mount)
  useEffect(() => {
    setLocalEnrollments(enrollments);
  }, [enrollments]);

  const filteredStudents = students.filter(s => 
    s.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    s.studentId.includes(searchTerm) || 
    s.grade.includes(searchTerm)
  ).sort((a,b) => {
    if (a.grade !== b.grade) return a.grade.localeCompare(b.grade);
    if (a.room !== b.room) return a.room.localeCompare(b.room);
    return a.number - b.number;
  });

  const toggleStudent = (studentId: string) => {
    if (!selectedSubject) return;
    const current = localEnrollments[selectedSubject] || [];
    const updated = current.includes(studentId) 
      ? current.filter(id => id !== studentId) 
      : [...current, studentId];

    setLocalEnrollments({ ...localEnrollments, [selectedSubject]: updated });
    setIsDirty(true);
  };

  const handleSelectAll = () => {
    if (!selectedSubject) return;
    const current = localEnrollments[selectedSubject] || [];
    const filteredIds = filteredStudents.map(s => s.studentId);

    // Combine current with filtered IDs, ensuring uniqueness
    const updated = Array.from(new Set([...current, ...filteredIds]));

    setLocalEnrollments({ ...localEnrollments, [selectedSubject]: updated });
    setIsDirty(true);
  };

  const handleDeselectAll = () => {
    if (!selectedSubject) return;
    const current = localEnrollments[selectedSubject] || [];
    const filteredIds = filteredStudents.map(s => s.studentId);

    // Remove filtered IDs from current
    const updated = current.filter(id => !filteredIds.includes(id));

    setLocalEnrollments({ ...localEnrollments, [selectedSubject]: updated });
    setIsDirty(true);
  };

  const handleSave = () => {
    if (!selectedSubject) return;
    setEnrollments(localEnrollments);
    storageService.saveEnrollment(localEnrollments);
    setIsDirty(false);
    alert('บันทึกข้อมูลการลงทะเบียนเรียนสำเร็จ!');
  };

  const currentEnrolled = selectedSubject ? (localEnrollments[selectedSubject] || []) : [];

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* Header Controls */}
      <div className="bg-white p-6 rounded-[2rem] border border-gray-100 shadow-sm space-y-4">
        <div className="flex flex-col md:flex-row gap-4 items-end">
          <div className="flex-1 w-full space-y-2">
            <label className="text-sm font-bold text-gray-700">เลือกวิชาที่จะลงทะเบียน</label>
            <select 
              className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-indigo-500 bg-gray-50/50"
              value={selectedSubject}
              onChange={e => {
                setSelectedSubject(e.target.value);
                setSearchTerm(''); // Clear search when subject changes
              }}
            >
              <option value="">-- เลือกวิชา --</option>
              {subjects.map(sub => <option key={sub.id} value={sub.code}>{sub.code} - {sub.name} ({sub.grade})</option>)}
            </select>
          </div>
          <div className="flex-1 w-full relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input 
              className="w-full pl-10 pr-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-indigo-500 bg-gray-50/50"
              placeholder="ค้นหาตามชื่อ/รหัส/ชั้น..."
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
        </div>

        {selectedSubject && (
          <div className="flex flex-wrap items-center justify-between gap-3 pt-2 border-t border-gray-50">
            <div className="flex gap-2">
              <button 
                onClick={handleSelectAll}
                className="flex items-center gap-2 px-4 py-2 bg-emerald-50 text-emerald-700 border border-emerald-100 rounded-xl text-sm font-bold hover:bg-emerald-100 transition-all"
              >
                <CheckSquare size={16} />
                เลือกทั้งหมดที่เจอ
              </button>
              <button 
                onClick={handleDeselectAll}
                className="flex items-center gap-2 px-4 py-2 bg-gray-50 text-gray-600 border border-gray-200 rounded-xl text-sm font-bold hover:bg-gray-100 transition-all"
              >
                <Square size={16} />
                ยกเลิกทั้งหมดที่เจอ
              </button>
            </div>

            <div className="flex items-center gap-4">
              {isDirty && (
                <span className="text-amber-600 text-xs font-bold flex items-center gap-1 animate-pulse">
                  <AlertCircle size={14} />
                  มีข้อมูลที่ยังไม่บันทึก
                </span>
              )}
              <button 
                onClick={handleSave}
                className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-bold shadow-lg transition-all ${
                  isDirty 
                    ? 'bg-indigo-600 text-white shadow-indigo-100 hover:bg-indigo-700' 
                    : 'bg-gray-200 text-gray-400 shadow-none cursor-not-allowed'
                }`}
                disabled={!isDirty}
              >
                <Save size={18} />
                บันทึกข้อมูล
              </button>
            </div>
          </div>
        )}
      </div>

      {!selectedSubject ? (
        <div className="bg-indigo-50 py-20 rounded-[2.5rem] border border-dashed border-indigo-200 flex flex-col items-center text-center">
