import Dexie from 'dexie';
import type { Table } from 'dexie';
import { Student, Subject, AttendanceSession, SubjectScoreSheet, TelegramConfig } from '../types';

export class SmartClassDB extends Dexie {
  students!: Table<Student>;
  subjects!: Table<Subject>;
  attendance!: Table<AttendanceSession>;
  scores!: Table<SubjectScoreSheet>;
  telegram!: Table<TelegramConfig>;
  enrollment!: Table<{ subjectCode: string, studentIds: string[] }>;

  constructor() {
    super('SmartClassDB');
    // Fix: Using default import and casting 'this' to any to ensure 'version' is recognized as an inherited method from Dexie.
    (this as any).version(1).stores({
      students: '++id, studentId, fullName, grade, room',
      subjects: '++id, code, name, grade',
      attendance: '++id, subjectCode, date',
      scores: 'subjectCode',
      telegram: 'subjectCode',
      enrollment: 'subjectCode'
    });
  }
}

export const db = new SmartClassDB();

export const storageService = {
  // Students
  getStudents: async (): Promise<Student[]> => await db.students.toArray(),
  saveStudents: async (data: Student[]) => {
    await db.students.clear();
    await db.students.bulkAdd(data);
  },

  // Subjects
  getSubjects: async (): Promise<Subject[]> => await db.subjects.toArray(),
  saveSubjects: async (data: Subject[]) => {
    await db.subjects.clear();
    await db.subjects.bulkAdd(data);
  },

  // Attendance
  getAttendance: async (): Promise<AttendanceSession[]> => await db.attendance.toArray(),
  saveAttendance: async (data: AttendanceSession[]) => {
    await db.attendance.clear();
    await db.attendance.bulkAdd(data);
  },

  // Scores
  getScores: async (): Promise<SubjectScoreSheet[]> => await db.scores.toArray(),
  saveScores: async (data: SubjectScoreSheet[]) => {
    await db.scores.clear();
    await db.scores.bulkAdd(data);
  },

  // Telegram
  getTelegram: async (): Promise<TelegramConfig[]> => await db.telegram.toArray(),
  saveTelegram: async (data: TelegramConfig[]) => {
    await db.telegram.clear();
    await db.telegram.bulkAdd(data);
  },

  // Enrollment
  getEnrollment: async (): Promise<Record<string, string[]>> => {
    const list = await db.enrollment.toArray();
    const result: Record<string, string[]> = {};
    list.forEach(item => {
      result[item.subjectCode] = item.studentIds;
    });
    return result;
  },
  saveEnrollment: async (data: Record<string, string[]>) => {
    await db.enrollment.clear();
    const payload = Object.entries(data).map(([code, ids]) => ({ subjectCode: code, studentIds: ids }));
    await db.enrollment.bulkAdd(payload);
  },

  // Backup & Restore helpers
  getAllData: async () => {
    return {
      STUDENTS: await db.students.toArray(),
      SUBJECTS: await db.subjects.toArray(),
      ATTENDANCE: await db.attendance.toArray(),
      SCORES: await db.scores.toArray(),
      TELEGRAM: await db.telegram.toArray(),
      ENROLLMENT: await storageService.getEnrollment()
    };
  },

  restoreAllData: async (data: any) => {
    try {
      // Fix: Cast the 'db' instance to any to resolve errors where 'transaction' is not recognized as an inherited property from Dexie.
      await (db as any).transaction('rw', [db.students, db.subjects, db.attendance, db.scores, db.telegram, db.enrollment], async () => {
        if (data.STUDENTS) { await db.students.clear(); await db.students.bulkAdd(data.STUDENTS); }
        if (data.SUBJECTS) { await db.subjects.clear(); await db.subjects.bulkAdd(data.SUBJECTS); }
        if (data.ATTENDANCE) { await db.attendance.clear(); await db.attendance.bulkAdd(data.ATTENDANCE); }
        if (data.SCORES) { await db.scores.clear(); await db.scores.bulkAdd(data.SCORES); }
        if (data.TELEGRAM) { await db.telegram.clear(); await db.telegram.bulkAdd(data.TELEGRAM); }
        if (data.ENROLLMENT) { await storageService.saveEnrollment(data.ENROLLMENT); }
      });
      return true;
    } catch (e) {
      console.error("Restore failed", e);
      return false;
    }
  },

  clearAllData: async () => {
    // Fix: Cast the 'db' instance to any to resolve errors where 'transaction' is not recognized as an inherited property from Dexie.
    await (db as any).transaction('rw', [db.students, db.subjects, db.attendance, db.scores, db.telegram, db.enrollment], async () => {
      await db.students.clear();
      await db.subjects.clear();
      await db.attendance.clear();
      await db.scores.clear();
      await db.telegram.clear();
      await db.enrollment.clear();
    });
  }
};

