        setEnrollments(await storageService.getEnrollment());
        setAttendance(await storageService.getAttendance());
        setScores(await storageService.getScores());
        setTelegramConfigs(await storageService.getTelegram());
      } catch (error) {
        console.error("Supabase Initialization error", error);
      } finally {
        setIsLoading(false);
      }
    };

    initData();

    // Check local storage for existing session
    const savedRole = localStorage.getItem('smart_class_role') as UserRole;
    if (savedRole) setRole(savedRole);
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const adminPass = 'admin1234';
    const teacherPass = 'teacher1234';

    const isCorrect = (showPassPrompt.targetRole === UserRole.ADMIN && passwordInput === adminPass) ||
                      (showPassPrompt.targetRole === UserRole.TEACHER && passwordInput === teacherPass);

    if (isCorrect) {
      setRole(showPassPrompt.targetRole);
      localStorage.setItem('smart_class_role', showPassPrompt.targetRole!);
      setShowPassPrompt({show: false, targetRole: null});
      setPasswordInput('');
      setAuthError('');
    } else {
      setAuthError('รหัสผ่านไม่ถูกต้อง กรุณาลองใหม่');
    }
  };

  const handleLogout = () => {
    setRole(null);
    localStorage.removeItem('smart_class_role');
  };

  const NavItem = ({ to, icon: Icon, label, color = "indigo" }: { to: string; icon: any; label: string; color?: string }) => {
    const location = useLocation();
    const isActive = location.pathname === to;

    const activeClass = color === "emerald" ? "bg-emerald-600 shadow-emerald-200" : (color === "amber" ? "bg-amber-600 shadow-amber-200" : "bg-indigo-600 shadow-indigo-200");
    const hoverClass = color === "emerald" ? "hover:bg-emerald-50 hover:text-emerald-600" : (color === "amber" ? "hover:bg-amber-50 hover:text-amber-600" : "hover:bg-indigo-50 hover:text-indigo-600");

    return (
      <Link
        to={to}
        onClick={() => setIsSidebarOpen(false)}
        className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
          isActive 
            ? `${activeClass} text-white shadow-lg` 
            : `text-gray-600 ${hoverClass}`
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </Link>
    );
  };

  if (isLoading) {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-white space-y-6">
        <div className="relative">
          <div className="w-20 h-20 border-4 border-emerald-100 rounded-full"></div>
          <div className="absolute inset-0 w-20 h-20 border-4 border-emerald-600 rounded-full border-t-transparent animate-spin"></div>
          <Cloud className="absolute inset-0 m-auto text-emerald-600" size={32} />
        </div>
        <div className="text-center">
          <h2 className="text-xl font-bold text-gray-900 leading-tight">Smart Classroom</h2>
          <p className="text-gray-500 animate-pulse">กำลังซิงค์ข้อมูล Cloud (Supabase)...</p>
        </div>
      </div>
    );
  }

  // Landing Page
  if (!role && !showPassPrompt.show) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-indigo-50 via-white to-emerald-50 flex items-center justify-center p-6">
        <div className="w-full max-w-4xl grid grid-cols-1 md:grid-cols-3 gap-6 animate-in fade-in zoom-in-95 duration-700">
          <div className="col-span-full text-center mb-8 space-y-4">
            <div className="w-20 h-20 bg-indigo-600 rounded-[2rem] flex items-center justify-center text-white mx-auto shadow-2xl shadow-indigo-200 mb-6">
              <GraduationCap size={48} />
            </div>
            <h1 className="text-4xl font-black text-gray-900 tracking-tight">ระบบบริหารจัดการห้องเรียน</h1>
            <p className="text-lg text-gray-500 font-medium">โรงเรียนน้ำคำวิทยา (Online System)</p>
          </div>

          {[
            { role: UserRole.ADMIN, title: 'ผู้ดูแลระบบ/งานทะเบียน', desc: 'จัดการวิชา, นักเรียน และข้อมูลระบบ', icon: ShieldAlert, color: 'indigo' },
            { role: UserRole.TEACHER, title: 'ครูประจำวิชา', desc: 'เช็คชื่อ, บันทึกคะแนน และดูภาพรวม', icon: UserCheck, color: 'blue' },
            { role: UserRole.STUDENT, title: 'นักเรียน', desc: 'ดูการเข้าเรียน และผลคะแนนรายวิชา', icon: Users, color: 'emerald' }
          ].map((item, i) => (
            <button
              key={i}
              onClick={() => {
                if (item.role === UserRole.STUDENT) {
                  setRole(UserRole.STUDENT);
                } else {
                  setShowPassPrompt({show: true, targetRole: item.role});
                }
              }}
              className="bg-white p-10 rounded-[2.5rem] shadow-xl border border-gray-100 flex flex-col items-center text-center group hover:scale-105 transition-all duration-300 active:scale-95"
            >
              <div className={`w-20 h-20 rounded-3xl mb-6 flex items-center justify-center transition-all ${
                item.color === 'indigo' ? 'bg-indigo-50 text-indigo-600 group-hover:bg-indigo-600 group-hover:text-white' : 
                item.color === 'blue' ? 'bg-blue-50 text-blue-600 group-hover:bg-blue-600 group-hover:text-white' : 
                'bg-emerald-50 text-emerald-600 group-hover:bg-emerald-600 group-hover:text-white'
              }`}>
                <item.icon size={40} />
              </div>
              <h3 className="text-xl font-bold text-gray-900 mb-2">{item.title}</h3>
              <p className="text-gray-500 text-sm font-medium leading-relaxed">{item.desc}</p>
            </button>
          ))}
        </div>
      </div>
    );
  }

  // Password Prompt Overlay
  if (showPassPrompt.show) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center p-6">
        <div className="w-full max-w-md bg-white p-10 rounded-[3rem] shadow-2xl border border-gray-100 animate-in zoom-in-95 duration-300">
          <button onClick={() => setShowPassPrompt({show: false, targetRole: null})} className="mb-6 p-2 text-gray-400 hover:bg-gray-100 rounded-2xl"><X /></button>
          <div className="flex flex-col items-center text-center mb-8">
            <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center mb-4">
              <Lock size={32} />
            </div>
            <h2 className="text-2xl font-black text-gray-900">ระบุรหัสผ่านเข้าใช้งาน</h2>
            <p className="text-gray-500 font-medium mt-1">
              เข้าถึงในฐานะ: {showPassPrompt.targetRole === UserRole.ADMIN ? 'แอดมิน/งานทะเบียน' : 'ครูประจำวิชา'}
            </p>
          </div>
          <form onSubmit={handleLogin} className="space-y-4">
            <input 
              autoFocus
              type="password"
              className="w-full px-6 py-4 rounded-2xl border-2 border-gray-100 focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 outline-none transition-all text-center text-xl font-bold tracking-widest"
              placeholder="••••••••"
              value={passwordInput}
              onChange={e => setPasswordInput(e.target.value)}
            />
            {authError && <p className="text-red-500 text-sm font-bold text-center">{authError}</p>}
            <button className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-bold shadow-lg shadow-indigo-100 hover:bg-indigo-700 active:scale-95 transition-all">
              ยืนยันรหัสผ่าน
            </button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <HashRouter>
      <div className="flex min-h-screen bg-gray-50">
        {isSidebarOpen && (
          <div className="fixed inset-0 bg-black/50 z-40 lg:hidden" onClick={() => setIsSidebarOpen(false)} />
        )}

        <aside className={`
          fixed inset-y-0 left-0 z-50 w-72 bg-white border-r border-gray-100 transition-transform duration-300 lg:static lg:translate-x-0
          ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
        `}>
          <div className="flex flex-col h-full p-6">
            <div className="flex items-center gap-3 mb-10 px-2">
              <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-100">
                <GraduationCap size={24} />
              </div>
              <div className="flex flex-col">
                <span className="font-bold text-lg text-gray-900 leading-tight">SmartClass</span>
                <span className="text-xs text-indigo-600 font-bold uppercase tracking-wider">
                  {role === UserRole.ADMIN ? 'ADMIN' : role === UserRole.TEACHER ? 'TEACHER' : 'STUDENT'}
                </span>
              </div>
            </div>

            <nav className="flex-1 space-y-1 overflow-y-auto no-scrollbar pb-6">
              {role !== UserRole.STUDENT && (
                <>
                  <NavItem to="/" icon={LayoutDashboard} label="ภาพรวม" />
                  {role === UserRole.ADMIN && (
                    <>
                      <NavItem to="/subjects" icon={BookOpen} label="จัดการวิชา" />
                      <NavItem to="/students" icon={Users} label="จัดการนักเรียน" />
                      <NavItem to="/enrollment" icon={ArrowRight} label="ลงทะเบียนเรียน" />
                    </>
                  )}
                  <NavItem to="/attendance" icon={ClipboardCheck} label="เช็คชื่อ" />
                  <NavItem to="/scores" icon={FileText} label="บันทึกคะแนน" />
                  <NavItem to="/calendar" icon={CalendarIcon} label="ปฏิทิน" />
                  {role === UserRole.ADMIN && (
                    <>
                      <NavItem to="/telegram" icon={Send} label="ตั้งค่า Telegram" />
                      <NavItem to="/backup" icon={Database} label="สำรองข้อมูล" color="amber" />
                    </>
                  )}
                </>
              )}

              <div className="pt-4 mt-4 border-t border-gray-100">
                <NavItem to="/student-portal" icon={UserCircle} label="มุมมองนักเรียน" color="emerald" />
              </div>
            </nav>

            <button 
              onClick={handleLogout}
              className="mt-6 flex items-center justify-center gap-3 px-4 py-4 rounded-2xl bg-red-50 text-red-600 font-bold hover:bg-red-100 transition-all border border-red-100"
            >
              <LogOut size={20} />
              <span>ออกจากระบบ</span>
            </button>
          </div>
        </aside>

        <main className="flex-1 flex flex-col min-w-0 h-screen overflow-hidden">
          <header className="h-16 flex items-center justify-between px-6 bg-white border-b border-gray-100 flex-shrink-0">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 text-gray-600 hover:bg-gray-100 rounded-lg"><Menu size={24} /></button>
            <div className="flex-1 flex justify-center lg:justify-start">
              <h1 className="text-lg font-bold text-gray-800 lg:ml-4">โรงเรียนน้ำคำวิทยา (Online System)</h1>
            </div>
          </header>

          <div className="flex-1 overflow-y-auto p-6 no-scrollbar">
            <div className="max-w-7xl mx-auto pb-12">
              <Routes>
                <Route path="/" element={<Dashboard subjects={subjects} students={students} attendance={attendance} scores={scores} />} />
                <Route path="/subjects" element={<Subjects subjects={subjects} setSubjects={setSubjects} />} />
                <Route path="/students" element={<Students students={students} setStudents={setStudents} />} />
                <Route path="/enrollment" element={<Enrollment subjects={subjects} students={students} enrollments={enrollments} setEnrollments={setEnrollments} />} />
                <Route path="/attendance" element={<Attendance subjects={subjects} students={students} enrollments={enrollments} attendance={attendance} setAttendance={setAttendance} />} />
                <Route path="/scores" element={<Scores subjects={subjects} students={students} enrollments={enrollments} scoreSheets={scores} setScoreSheets={setScores} attendance={attendance} />} />
                <Route path="/calendar" element={<CalendarView attendance={attendance} />} />
                <Route path="/telegram" element={<TelegramSettings subjects={subjects} telegramConfigs={telegramConfigs} setTelegramConfigs={setTelegramConfigs} />} />
                <Route path="/backup" element={<BackupRestore />} />
                <Route path="/student-portal" element={<StudentPortal subjects={subjects} students={students} enrollments={enrollments} attendance={attendance} scores={scores} />} />
              </Routes>
            </div>
            <footer className="mt-auto py-8 border-t border-gray-100 text-center space-y-2">
              <p className="text-sm font-medium text-gray-600">พัฒนาโดย: <span className="text-indigo-600 font-bold">นายธวัชชัย แก่นจักร์</span> ครู โรงเรียนน้ำคำวิทยา</p>
              <p className="text-xs text-gray-400 font-medium">Copyright © 2026 Smart Classroom Management System (Online Version)</p>
            </footer>
          </div>
        </main>
      </div>
    </HashRouter>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Subject, Student, SubjectScoreSheet, Score, AttendanceSession } from '../types';
import { storageService } from '../services/storageService';
import { geminiService } from '../services/geminiService';
import { Sparkles, Save, BrainCircuit, Plus, Trash2, Edit3, Settings2, X, AlertCircle, Info } from 'lucide-react';
import Modal, { ModalType } from './Modal';

interface ScoresProps {
  subjects: Subject[];
  students: Student[];
  enrollments: Record<string, string[]>;
  scoreSheets: SubjectScoreSheet[];
  setScoreSheets: React.Dispatch<React.SetStateAction<SubjectScoreSheet[]>>;
  attendance: AttendanceSession[];
}

const Scores: React.FC<ScoresProps> = ({ subjects, students, enrollments, scoreSheets, setScoreSheets, attendance }) => {
  const [selectedSubject, setSelectedSubject] = useState<string>('');
  const [currentSheet, setCurrentSheet] = useState<SubjectScoreSheet | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<string | null>(null);
  const [showAssignModal, setShowAssignModal] = useState(false);

  // Modal State
  const [modal, setModal] = useState<{isOpen: boolean, title: string, message: string, type: ModalType, onConfirm?: () => void}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const showAlert = (title: string, message: string, type: ModalType = 'info', onConfirm?: () => void) => {
    setModal({ isOpen: true, title, message, type, onConfirm });
  };

  // Load or Initialize ScoreSheet
  useEffect(() => {
    if (selectedSubject) {
      const sheet = scoreSheets.find(s => s.subjectCode === selectedSubject);
      if (sheet) {
        setCurrentSheet(JSON.parse(JSON.stringify(sheet))); // Deep copy
      } else {
        const enrolledIds = enrollments[selectedSubject] || [];
        const subject = subjects.find(s => s.code === selectedSubject);
        const newSheet: SubjectScoreSheet = {
          subjectCode: selectedSubject,
          scores: enrolledIds.map(id => ({
            studentId: id,
            collectScores: {},
            midterm: 0,
            final: 0,
            totalScore: 0,
            grade: '0'
          })),
          assignmentNames: {
            1: { name: 'งานที่ 1', maxScore: 10 }
          }
        };
        setCurrentSheet(newSheet);
      }
    } else {
      setCurrentSheet(null);
    }
  }, [selectedSubject, enrollments, scoreSheets, subjects]);

  const calculateTotalAndGrade = (score: Score, sheet: SubjectScoreSheet, subject: Subject) => {
    let totalStudentRaw = 0;
    let totalMaxPossible = 0;

    (Object.entries(sheet.assignmentNames) as [string, { name: string; maxScore: number }][]).forEach(([idx, config]) => {
      const studentScore = score.collectScores[parseInt(idx)] || 0;
      totalStudentRaw += studentScore;
      totalMaxPossible += config.maxScore;
    });

    const weightedCollect = totalMaxPossible > 0 
      ? (totalStudentRaw / totalMaxPossible) * subject.collectPercent 
      : 0;

    const midtermWeight = (score.midterm / 100) * subject.midtermPercent;
    const finalWeight = (score.final / 100) * subject.finalPercent;

    const total = weightedCollect + midtermWeight + finalWeight;
    const rounded = Math.round(total * 100) / 100;

    let grade = '0';
    if (rounded >= 80) grade = '4';
    else if (rounded >= 75) grade = '3.5';
    else if (rounded >= 70) grade = '3';
    else if (rounded >= 65) grade = '2.5';
    else if (rounded >= 60) grade = '2';
    else if (rounded >= 55) grade = '1.5';
    else if (rounded >= 50) grade = '1';

    return { total: rounded, grade };
  };

  const updateScore = (studentId: string, field: string, value: any, collectIndex?: number) => {
    if (!currentSheet || !selectedSubject) return;
    const subject = subjects.find(s => s.code === selectedSubject)!;

    const updatedScores = currentSheet.scores.map(s => {
      if (s.studentId === studentId) {
        let newScore = { ...s };
        if (collectIndex !== undefined) {
          const val = parseFloat(value);
          const max = currentSheet.assignmentNames[collectIndex].maxScore;
          newScore.collectScores = { ...s.collectScores, [collectIndex]: Math.min(val || 0, max) };
        } else {
          (newScore as any)[field] = parseFloat(value) || 0;
        }
        const { total, grade } = calculateTotalAndGrade(newScore, currentSheet, subject);
        newScore.totalScore = total;
        newScore.grade = grade;
        return newScore;
      }
      return s;
    });

    setCurrentSheet({ ...currentSheet, scores: updatedScores });
  };

  const addAssignment = () => {
    if (!currentSheet) return;
    const nextIdx = Math.max(0, ...Object.keys(currentSheet.assignmentNames).map(Number)) + 1;
    const updatedSheet = {
      ...currentSheet,
      assignmentNames: {
        ...currentSheet.assignmentNames,
        [nextIdx]: { name: `ระบุชื่องาน ${nextIdx}`, maxScore: 10 }
      }
    };
    setCurrentSheet(updatedSheet);
  };

  const removeAssignment = (idx: number) => {
    showAlert('ยืนยันการลบ', 'ข้อมูลคะแนนในงานนี้จะถูกลบออกจากทุกคนอย่างถาวร ต้องการลบหรือไม่?', 'confirm', () => {
      if (!currentSheet) return;
      const { [idx]: removed, ...rest } = currentSheet.assignmentNames;
      const updatedScores = currentSheet.scores.map(s => {
        const { [idx]: scoreRemoved, ...scoresRest } = s.collectScores;
        return { ...s, collectScores: scoresRest };
      });
      setCurrentSheet({ ...currentSheet, assignmentNames: rest, scores: updatedScores });
    });
  };

  const updateAssignmentConfig = (idx: number, field: 'name' | 'maxScore', value: any) => {
    if (!currentSheet) return;
    const updatedSheet = {
      ...currentSheet,
      assignmentNames: {
        ...currentSheet.assignmentNames,
        [idx]: { 
          ...currentSheet.assignmentNames[idx], 
          [field]: field === 'maxScore' ? (parseInt(value) || 0) : value 
        }
      }
    };
    setCurrentSheet(updatedSheet);
  };

  const saveSheet = async () => {
    if (!currentSheet) return;
    try {
      const updated = [...scoreSheets.filter(s => s.subjectCode !== currentSheet.subjectCode), currentSheet];
      await storageService.saveScores(updated);
      setScoreSheets(updated);
      showAlert('สำเร็จ', 'บันทึกข้อมูลคะแนนลงระบบคลาวด์เรียบร้อยแล้ว', 'success');
    } catch (e) {
      showAlert('ผิดพลาด', 'ไม่สามารถบันทึกข้อมูลได้ กรุณาตรวจสอบการเชื่อมต่อ', 'error');
    }
  };

  const runAnalysis = async () => {
    if (!currentSheet || !selectedSubject) return;
    setIsAnalyzing(true);
    const subject = subjects.find(s => s.code === selectedSubject)!;
    const result = await geminiService.analyzePerformance(students, currentSheet.scores, subject.name);
    setAnalysisResult(result || '');
    setIsAnalyzing(false);
  };

  const subject = subjects.find(s => s.code === selectedSubject);

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <Modal 
        isOpen={modal.isOpen} 
        onClose={() => setModal({...modal, isOpen: false})} 
        onConfirm={modal.onConfirm}
        title={modal.title} 
        message={modal.message} 
        type={modal.type} 
      />

      {/* Header Controls */}
      <div className="bg-white p-6 rounded-[2rem] border border-gray-100 shadow-sm flex flex-col md:flex-row gap-4 items-end">
        <div className="flex-1 w-full space-y-2">
          <label className="text-sm font-bold text-gray-700">เลือกวิชาบันทึกคะแนน</label>
          <select 
            className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-indigo-500 bg-gray-50/50"
            value={selectedSubject}
            onChange={e => setSelectedSubject(e.target.value)}
          >
            <option value="">-- เลือกวิชา --</option>
            {subjects.map(sub => <option key={sub.id} value={sub.code}>{sub.code} - {sub.name} ({sub.grade})</option>)}
          </select>
        </div>

        {selectedSubject && (
          <div className="flex gap-2 w-full md:w-auto">
            <button 
              onClick={() => setShowAssignModal(!showAssignModal)}
              className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-amber-50 text-amber-700 border border-amber-200 px-5 py-3 rounded-xl font-bold hover:bg-amber-100 transition-all"
            >
              <Settings2 size={20} />
              <span>ตั้งค่างาน</span>
            </button>
            <button 
              disabled={isAnalyzing}
              onClick={runAnalysis}
              className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-purple-600 text-white px-5 py-3 rounded-xl font-bold shadow-lg shadow-purple-100 disabled:opacity-50"
            >
              <BrainCircuit size={20} />
              <span>AI วิเคราะห์</span>
            </button>
            <button 
              onClick={saveSheet}
              className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-indigo-600 text-white px-6 py-3 rounded-xl font-bold shadow-lg shadow-indigo-100 transition-all hover:bg-indigo-700"
            >
              <Save size={20} />
              <span>บันทึกฐานข้อมูล</span>
            </button>
          </div>
        )}
      </div>

      {showAssignModal && currentSheet && (
        <div className="bg-amber-50 p-6 rounded-[2rem] border border-amber-100 space-y-4 animate-in slide-in-from-top duration-300">
          <div className="flex items-center justify-between">
            <h3 className="font-bold text-amber-900 flex items-center gap-2">
              <Settings2 size={18} /> จัดการรายการงานและคะแนนเต็ม
            </h3>
            <button onClick={() => setShowAssignModal(false)} className="text-amber-400 hover:text-amber-600"><X size={20}/></button>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {(Object.entries(currentSheet.assignmentNames) as [string, { name: string; maxScore: number }][]).map(([idx, config]) => (
              <div key={idx} className="bg-white p-4 rounded-2xl border border-amber-200 flex gap-3 items-center">
                <div className="flex-1 space-y-2">
                  <input 
                    className="w-full text-sm font-bold border-b border-gray-100 outline-none focus:border-amber-500"
                    value={config.name}
                    onChange={e => updateAssignmentConfig(parseInt(idx), 'name', e.target.value)}
                    placeholder="ชื่อเรียกงาน"
                  />
                  <div className="flex items-center gap-2">
                    <span className="text-[10px] font-bold text-gray-400 uppercase">เต็ม</span>
                    <input 
                      type="number"
                      className="w-16 text-sm font-bold text-amber-600 outline-none"
                      value={config.maxScore}
                      onChange={e => updateAssignmentConfig(parseInt(idx), 'maxScore', e.target.value)}
                    />
                  </div>
                </div>
                <button 
                  onClick={() => removeAssignment(parseInt(idx))}
                  className="p-2 text-red-300 hover:text-red-500 hover:bg-red-50 rounded-lg"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            ))}
            <button 
              onClick={addAssignment}
              className="border-2 border-dashed border-amber-300 rounded-2xl flex flex-col items-center justify-center p-4 text-amber-600 hover:bg-amber-100/50 transition-all"
            >
              <Plus size={24} />
              <span className="text-xs font-bold mt-1">เพิ่มช่องคะแนนงาน</span>
            </button>
          </div>
          <div className="flex items-start gap-2 text-amber-700 text-xs bg-white/50 p-3 rounded-xl">
            <Info size={14} className="mt-0.5" />
            <p>คะแนนเก็บทั้งหมดจะถูกนำไปคำนวณถ่วงน้ำหนักให้เหลือ <b>{subject?.collectPercent}%</b> ตามโครงสร้างวิชาที่ตั้งไว้</p>
          </div>
        </div>
      )}

      {analysisResult && (
        <div className="bg-purple-50 p-6 rounded-3xl border border-purple-100 animate-in fade-in slide-in-from-bottom duration-500 relative">
          <button onClick={() => setAnalysisResult(null)} className="absolute top-4 right-4 text-purple-400 hover:text-purple-600">
            <X size={20} />
          </button>
          <div className="flex items-center gap-2 mb-4 text-purple-700 font-bold">
            <Sparkles size={20} />
            <span>AI สรุปผลการเรียนอัจฉริยะ</span>
          </div>
          <div className="text-purple-900 text-sm leading-relaxed whitespace-pre-wrap">
            {analysisResult}
          </div>
        </div>
      )}

      {!currentSheet ? (
        <div className="bg-indigo-50 py-20 rounded-[2.5rem] text-center text-indigo-900 border border-dashed border-indigo-200">
          <Sparkles size={32} className="mx-auto mb-4 text-indigo-400" />
          <p className="font-bold">เลือกวิชาเพื่อเปิดสมุดบันทึกคะแนน</p>
        </div>
      ) : (
        <div className="bg-white rounded-[2.5rem] border border-gray-100 overflow-hidden shadow-sm">
          <div className="overflow-x-auto no-scrollbar">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b border-gray-100">
                <tr>
                  <th className="px-4 py-5 text-left font-bold text-gray-500 uppercase min-w-[60px]">เลขที่</th>
                  <th className="px-4 py-5 text-left font-bold text-gray-500 uppercase min-w-[200px]">ชื่อ-นามสกุล</th>
                  {(Object.entries(currentSheet.assignmentNames) as [string, { name: string; maxScore: number }][]).map(([idx, config]) => (
                    <th key={idx} className="px-2 py-5 text-center min-w-[100px] border-l border-gray-100/50">
                      <div className="flex flex-col items-center">
                        <span className="text-[10px] text-gray-400 font-bold uppercase truncate max-w-[80px]">{config.name}</span>
                        <span className="text-indigo-600 font-bold">เต็ม {config.maxScore}</span>
                      </div>
                    </th>
                  ))}
                  <th className="px-2 py-5 text-center min-w-[100px] bg-indigo-50/30 border-l border-gray-100">
                    <div className="flex flex-col items-center">
                      <span className="text-[10px] text-indigo-400 font-bold">กลางภาค</span>
                      <span className="text-indigo-600 font-bold">({subject?.midtermPercent}%)</span>
                    </div>
                  </th>
                  <th className="px-2 py-5 text-center min-w-[100px] bg-indigo-50/30">
                    <div className="flex flex-col items-center">
                      <span className="text-[10px] text-indigo-400 font-bold">ปลายภาค</span>
                      <span className="text-indigo-600 font-bold">({subject?.finalPercent}%)</span>
                    </div>
                  </th>
                  <th className="px-4 py-5 text-center font-bold text-indigo-900 uppercase min-w-[80px] bg-indigo-100/50">รวม</th>
                  <th className="px-4 py-5 text-center font-bold text-indigo-900 uppercase min-w-[80px] bg-indigo-100/50">เกรด</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {currentSheet.scores.sort((a,b) => {
                  const stA = students.find(s => s.studentId === a.studentId);
                  const stB = students.find(s => s.studentId === b.studentId);
                  return (stA?.number || 0) - (stB?.number || 0);
                }).map(score => {
                  const student = students.find(s => s.studentId === score.studentId);
                  return (
                    <tr key={score.studentId} className="hover:bg-indigo-50/20 transition-colors">
                      <td className="px-4 py-4 text-gray-400 font-bold text-center">{student?.number}</td>
                      <td className="px-4 py-4">
                        <p className="font-bold text-gray-900">{student?.fullName}</p>
                        <p className="text-[10px] text-gray-400 font-mono">{student?.studentId}</p>
                      </td>
                      {Object.keys(currentSheet.assignmentNames).map(idx => (
                        <td key={idx} className="px-2 py-4 border-l border-gray-100/30">
                          <input 
                            type="number" 
                            className="w-full px-2 py-2 rounded-xl bg-gray-50 border border-transparent focus:border-indigo-300 focus:bg-white text-center font-bold text-gray-800 outline-none transition-all" 
                            value={score.collectScores[parseInt(idx)] === 0 ? '' : (score.collectScores[parseInt(idx)] || '')} 
                            onChange={e => updateScore(score.studentId, '', e.target.value, parseInt(idx))}
                            placeholder="0"
                          />
                        </td>
                      ))}
                      <td className="px-2 py-4 bg-indigo-50/10 border-l border-gray-100">
                        <input 
                          type="number" 
                          className="w-full px-2 py-2 rounded-xl bg-white border border-indigo-100 text-center font-bold text-indigo-900 focus:ring-2 focus:ring-indigo-500/20 outline-none" 
                          value={score.midterm === 0 ? '' : (score.midterm || '')} 
                          onChange={e => updateScore(score.studentId, 'midterm', e.target.value)}
                          placeholder="0"
                        />
                      </td>
                      <td className="px-2 py-4 bg-indigo-50/10">
                        <input 
                          type="number" 
                          className="w-full px-2 py-2 rounded-xl bg-white border border-indigo-100 text-center font-bold text-indigo-900 focus:ring-2 focus:ring-indigo-500/20 outline-none" 
                          value={score.final === 0 ? '' : (score.final || '')} 
                          onChange={e => updateScore(score.studentId, 'final', e.target.value)}
                          placeholder="0"
                        />
                      </td>
                      <td className="px-4 py-4 text-center bg-indigo-100/20">
                        <span className="text-lg font-black text-gray-900">{score.totalScore}</span>
                      </td>
                      <td className="px-4 py-4 text-center bg-indigo-100/20">
                        <span className={`inline-block px-3 py-1 rounded-full text-xs font-black shadow-sm ${
                          parseFloat(score.grade) >= 3 ? 'bg-emerald-500 text-white' : 
                          parseFloat(score.grade) >= 1 ? 'bg-indigo-500 text-white' : 
                          'bg-red-500 text-white'
                        }`}>
                          {score.grade}
                        </span>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default Scores;

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Link, useLocation, useNavigate } from 'react-router-dom';
import { 
  LayoutDashboard, 
  BookOpen, 
  Users, 
  ClipboardCheck, 
  GraduationCap, 
  Calendar as CalendarIcon, 
  Settings, 
  FileText,
  Plus,
  ArrowRight,
  ChevronRight,
  Menu,
  X,
  Send,
  Sparkles,
  UserCircle,
  Database,
  Loader2,
  Cloud,
  LogOut,
  ShieldAlert,
  Lock,
  Search,
  UserCheck
} from 'lucide-react';
import { storageService } from './services/storageService';
import { Student, Subject, AttendanceSession, SubjectScoreSheet, TelegramConfig, UserRole } from './types';
import { initialStudents } from './initialStudents';
import { initialSubjects } from './initialSubjects';

// Components
import Dashboard from './components/Dashboard';
import Subjects from './components/Subjects';
import Students from './components/Students';
import Enrollment from './components/Enrollment';
import Attendance from './components/Attendance';
import Scores from './components/Scores';
import CalendarView from './components/CalendarView';
import TelegramSettings from './components/TelegramSettings';
import StudentPortal from './components/StudentPortal';
import BackupRestore from './components/BackupRestore';
import Modal from './components/Modal';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [students, setStudents] = useState<Student[]>([]);
  const [enrollments, setEnrollments] = useState<Record<string, string[]>>({});
  const [attendance, setAttendance] = useState<AttendanceSession[]>([]);
  const [scores, setScores] = useState<SubjectScoreSheet[]>([]);
  const [telegramConfigs, setTelegramConfigs] = useState<TelegramConfig[]>([]);

  // Password Login state
  const [showPassPrompt, setShowPassPrompt] = useState<{show: boolean, targetRole: UserRole | null}>({show: false, targetRole: null});
  const [passwordInput, setPasswordInput] = useState('');
  const [authError, setAuthError] = useState('');

  // Initialize data from Supabase
  useEffect(() => {
    const initData = async () => {
      try {
        let storedSubjects = await storageService.getSubjects();
        if (storedSubjects.length === 0) {
          await storageService.saveSubjects(initialSubjects);
          storedSubjects = initialSubjects;
        }
        setSubjects(storedSubjects);

        let storedStudents = await storageService.getStudents();
        if (storedStudents.length === 0) {
          await storageService.saveStudents(initialStudents);
          storedStudents = initialStudents;
        }
        setStudents(storedStudents);

        setEnrollments(await storageService.getEnrollment());
        setAttendance(await storageService.getAttendance());
        setScores(await storageService.getScores());
        setTelegramConfigs(await storageService.getTelegram());
      } catch (error) {
        console.error("Supabase Initialization error", error);
      } finally {
        setIsLoading(false);
      }
    };

    initData();

    // Check local storage for existing session
    const savedRole = localStorage.getItem('smart_class_role') as UserRole;
    if (savedRole) setRole(savedRole);
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const adminPass = 'admin1234';
    const teacherPass = 'teacher1234';

    const isCorrect = (showPassPrompt.targetRole === UserRole.ADMIN && passwordInput === adminPass) ||
                      (showPassPrompt.targetRole === UserRole.TEACHER && passwordInput === teacherPass);

    if (isCorrect) {
      setRole(showPassPrompt.targetRole);
      localStorage.setItem('smart_class_role', showPassPrompt.targetRole!);
      setShowPassPrompt({show: false, targetRole: null});
      setPasswordInput('');
      setAuthError('');
    } else {
      setAuthError('รหัสผ่านไม่ถูกต้อง กรุณาลองใหม่');
    }
  };

  const handleLogout = () => {
    setRole(null);
    localStorage.removeItem('smart_class_role');
  };

  const NavItem = ({ to, icon: Icon, label, color = "indigo" }: { to: string; icon: any; label: string; color?: string }) => {
    const location = useLocation();
    const isActive = location.pathname === to;

    const activeClass = color === "emerald" ? "bg-emerald-600 shadow-emerald-200" : (color === "amber" ? "bg-amber-600 shadow-amber-200" : "bg-indigo-600 shadow-indigo-200");
    const hoverClass = color === "emerald" ? "hover:bg-emerald-50 hover:text-emerald-600" : (color === "amber" ? "hover:bg-amber-50 hover:text-amber-600" : "hover:bg-indigo-50 hover:text-indigo-600");

    return (
      <Link
        to={to}
        onClick={() => setIsSidebarOpen(false)}
        className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
          isActive 
            ? `${activeClass} text-white shadow-lg` 
            : `text-gray-600 ${hoverClass}`
        }`}
      >
        <Icon size={20} />
        <span className="font-medium">{label}</span>
      </Link>
    );
  };

  if (isLoading) {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-white space-y-6">
        <div className="relative">
          <div className="w-20 h-20 border-4 border-emerald-100 rounded-full"></div>
          <div className="absolute inset-0 w-20 h-20 border-4 border-emerald-600 rounded-full border-t-transparent animate-spin"></div>
          <Cloud className="absolute inset-0 m-auto text-emerald-600" size={32} />
        </div>
        <div className="text-center">
          <h2 className="text-xl font-bold text-gray-900 leading-tight">KruB.T. Smart Classroom</h2>
          <p className="text-gray-500 animate-pulse">กำลังซิงค์ข้อมูล Cloud (Supabase)...</p>
        </div>
      </div>
    );
  }

  // Landing Page
  if (!role && !showPassPrompt.show) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-indigo-50 via-white to-emerald-50 flex items-center justify-center p-6">
        <div className="w-full max-w-4xl grid grid-cols-1 md:grid-cols-3 gap-6 animate-in fade-in zoom-in-95 duration-700">
          <div className="col-span-full text-center mb-8 space-y-4">
            <div className="w-20 h-20 bg-indigo-600 rounded-[2rem] flex items-center justify-center text-white mx-auto shadow-2xl shadow-indigo-200 mb-6">
              <GraduationCap size={48} />
            </div>
            <h1 className="text-4xl font-black text-gray-900 tracking-tight underline decoration-indigo-200 decoration-8 underline-offset-8">KruB.T. Smart Classroom</h1>
            <p className="text-lg text-gray-500 font-medium">โรงเรียนน้ำคำวิทยา (ระบบบริหารจัดการห้องเรียนออนไลน์)</p>
          </div>

          {[
            { role: UserRole.ADMIN, title: 'ผู้ดูแลระบบ/งานทะเบียน', desc: 'จัดการวิชา, นักเรียน และข้อมูลระบบ', icon: ShieldAlert, color: 'indigo' },
            { role: UserRole.TEACHER, title: 'ครูประจำวิชา', desc: 'เช็คชื่อ, บันทึกคะแนน และดูภาพรวม', icon: UserCheck, color: 'blue' },
            { role: UserRole.STUDENT, title: 'นักเรียน', desc: 'ดูการเข้าเรียน และผลคะแนนรายวิชา', icon: Users, color: 'emerald' }
          ].map((item, i) => (
            <button
              key={i}
              onClick={() => {
                if (item.role === UserRole.STUDENT) {
                  setRole(UserRole.STUDENT);
                } else {
                  setShowPassPrompt({show: true, targetRole: item.role});
                }
              }}
              className="bg-white p-10 rounded-[2.5rem] shadow-xl border border-gray-100 flex flex-col items-center text-center group hover:scale-105 transition-all duration-300 active:scale-95"
            >
              <div className={`w-20 h-20 rounded-3xl mb-6 flex items-center justify-center transition-all ${
                item.color === 'indigo' ? 'bg-indigo-50 text-indigo-600 group-hover:bg-indigo-600 group-hover:text-white' : 
                item.color === 'blue' ? 'bg-blue-50 text-blue-600 group-hover:bg-blue-600 group-hover:text-white' : 
                'bg-emerald-50 text-emerald-600 group-hover:bg-emerald-600 group-hover:text-white'
              }`}>
                <item.icon size={40} />
              </div>
              <h3 className="text-xl font-bold text-gray-900 mb-2">{item.title}</h3>
              <p className="text-gray-500 text-sm font-medium leading-relaxed">{item.desc}</p>
            </button>
          ))}
        </div>
      </div>
    );
  }

  // Password Prompt Overlay
  if (showPassPrompt.show) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center p-6">
        <div className="w-full max-w-md bg-white p-10 rounded-[3rem] shadow-2xl border border-gray-100 animate-in zoom-in-95 duration-300">
          <button onClick={() => setShowPassPrompt({show: false, targetRole: null})} className="mb-6 p-2 text-gray-400 hover:bg-gray-100 rounded-2xl"><X /></button>
          <div className="flex flex-col items-center text-center mb-8">
            <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center mb-4">
              <Lock size={32} />
            </div>
            <h2 className="text-2xl font-black text-gray-900">ระบุรหัสผ่านเข้าใช้งาน</h2>
            <p className="text-gray-500 font-medium mt-1">
              เข้าถึงในฐานะ: {showPassPrompt.targetRole === UserRole.ADMIN ? 'แอดมิน/งานทะเบียน' : 'ครูประจำวิชา'}
            </p>
          </div>
          <form onSubmit={handleLogin} className="space-y-4">
            <input 
              autoFocus
              type="password"
              className="w-full px-6 py-4 rounded-2xl border-2 border-gray-100 focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 outline-none transition-all text-center text-xl font-bold tracking-widest"
              placeholder="••••••••"
              value={passwordInput}
              onChange={e => setPasswordInput(e.target.value)}
            />
            {authError && <p className="text-red-500 text-sm font-bold text-center">{authError}</p>}
            <button className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-bold shadow-lg shadow-indigo-100 hover:bg-indigo-700 active:scale-95 transition-all">
              ยืนยันรหัสผ่าน
            </button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <HashRouter>
      <div className="flex min-h-screen bg-gray-50">
        {isSidebarOpen && (
          <div className="fixed inset-0 bg-black/50 z-40 lg:hidden" onClick={() => setIsSidebarOpen(false)} />
        )}

        <aside className={`
          fixed inset-y-0 left-0 z-50 w-72 bg-white border-r border-gray-100 transition-transform duration-300 lg:static lg:translate-x-0
          ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
        `}>
          <div className="flex flex-col h-full p-6">
            <div className="flex items-center gap-3 mb-10 px-2">
              <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-100">
                <GraduationCap size={24} />
              </div>
              <div className="flex flex-col">
                <span className="font-bold text-lg text-gray-900 leading-tight">KruB.T.</span>
                <span className="text-xs text-indigo-600 font-bold uppercase tracking-wider">
                  Smart Classroom
                </span>
              </div>
            </div>

            <nav className="flex-1 space-y-1 overflow-y-auto no-scrollbar pb-6">
              {role !== UserRole.STUDENT && (
                <>
                  <NavItem to="/" icon={LayoutDashboard} label="ภาพรวม" />
                  {role === UserRole.ADMIN && (
                    <>
                      <NavItem to="/subjects" icon={BookOpen} label="จัดการวิชา" />
                      <NavItem to="/students" icon={Users} label="จัดการนักเรียน" />
                      <NavItem to="/enrollment" icon={ArrowRight} label="ลงทะเบียนเรียน" />
                    </>
                  )}
                  <NavItem to="/attendance" icon={ClipboardCheck} label="เช็คชื่อ" />
                  <NavItem to="/scores" icon={FileText} label="บันทึกคะแนน" />
                  <NavItem to="/calendar" icon={CalendarIcon} label="ปฏิทิน" />
                  {role === UserRole.ADMIN && (
                    <>
                      <NavItem to="/telegram" icon={Send} label="ตั้งค่า Telegram" />
                      <NavItem to="/backup" icon={Database} label="สำรองข้อมูล" color="amber" />
                    </>
                  )}
                </>
              )}

              <div className="pt-4 mt-4 border-t border-gray-100">
                <NavItem to="/student-portal" icon={UserCircle} label="มุมมองนักเรียน" color="emerald" />
              </div>
            </nav>

            <button 
              onClick={handleLogout}
              className="mt-6 flex items-center justify-center gap-3 px-4 py-4 rounded-2xl bg-red-50 text-red-600 font-bold hover:bg-red-100 transition-all border border-red-100"
            >
              <LogOut size={20} />
              <span>ออกจากระบบ</span>
            </button>
          </div>
        </aside>

        <main className="flex-1 flex flex-col min-w-0 h-screen overflow-hidden">
          <header className="h-16 flex items-center justify-between px-6 bg-white border-b border-gray-100 flex-shrink-0">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 text-gray-600 hover:bg-gray-100 rounded-lg"><Menu size={24} /></button>
            <div className="flex-1 flex justify-center lg:justify-start">
              <h1 className="text-lg font-bold text-gray-800 lg:ml-4">KruB.T. Smart Classroom</h1>
            </div>
          </header>

          <div className="flex-1 overflow-y-auto p-6 no-scrollbar">
            <div className="max-w-7xl mx-auto pb-12">
              <Routes>
                <Route path="/" element={<Dashboard subjects={subjects} students={students} attendance={attendance} scores={scores} />} />
                <Route path="/subjects" element={<Subjects subjects={subjects} setSubjects={setSubjects} />} />
                <Route path="/students" element={<Students students={students} setStudents={setStudents} />} />
                <Route path="/enrollment" element={<Enrollment subjects={subjects} students={students} enrollments={enrollments} setEnrollments={setEnrollments} />} />
                <Route path="/attendance" element={<Attendance subjects={subjects} students={students} enrollments={enrollments} attendance={attendance} setAttendance={setAttendance} />} />
                <Route path="/scores" element={<Scores subjects={subjects} students={students} enrollments={enrollments} scoreSheets={scores} setScoreSheets={setScores} attendance={attendance} />} />
                <Route path="/calendar" element={<CalendarView attendance={attendance} />} />
                <Route path="/telegram" element={<TelegramSettings subjects={subjects} telegramConfigs={telegramConfigs} setTelegramConfigs={setTelegramConfigs} />} />
                <Route path="/backup" element={<BackupRestore />} />
                <Route path="/student-portal" element={<StudentPortal subjects={subjects} students={students} enrollments={enrollments} attendance={attendance} scores={scores} />} />
              </Routes>
            </div>
            <footer className="mt-auto py-8 border-t border-gray-100 text-center space-y-2">
              <p className="text-sm font-medium text-gray-600">พัฒนาโดย: <span className="text-indigo-600 font-bold">นายธวัชชัย แก่นจักร์</span> ครู โรงเรียนน้ำคำวิทยา</p>
              <p className="text-xs text-gray-400 font-medium">Copyright © 2026 KruB.T. Smart Classroom Management System</p>
            </footer>
          </div>
        </main>
      </div>
    </HashRouter>
  );
};

