import React, { useState, useEffect } from 'react';
import { AttendanceSession } from '../types';
import { ChevronLeft, ChevronRight, Link as LinkIcon, Calendar as CalendarIcon, X, Check, ExternalLink, Globe } from 'lucide-react';
import Modal, { ModalType } from './Modal';

interface CalendarViewProps {
  attendance: AttendanceSession[];
}

const CalendarView: React.FC<CalendarViewProps> = ({ attendance }) => {
  const [currentMonth, setCurrentMonth] = useState(new Date().getMonth());
  const [currentYear, setCurrentYear] = useState(new Date().getFullYear());
  const [viewMode, setViewMode] = useState<'system' | 'google'>('system');
  const [googleCalendarUrl, setGoogleCalendarUrl] = useState<string>(localStorage.getItem('google_calendar_url') || '');
  const [isSettingUrl, setIsSettingUrl] = useState(false);
  const [urlInput, setUrlInput] = useState(googleCalendarUrl);

  const [modal, setModal] = useState<{isOpen: boolean, title: string, message: string, type: ModalType}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
  const firstDay = new Date(currentYear, currentMonth, 1).getDay();
  const monthNames = ["มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน", "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"];

  const prevMonth = () => {
    if (currentMonth === 0) { setCurrentMonth(11); setCurrentYear(currentYear - 1); }
    else setCurrentMonth(currentMonth - 1);
  };

  const nextMonth = () => {
    if (currentMonth === 11) { setCurrentMonth(0); setCurrentYear(currentYear + 1); }
    else setCurrentMonth(currentMonth + 1);
  };

  const handleSaveUrl = () => {
    let finalUrl = urlInput.trim();
    // Simple check to help user if they paste the full iframe code
    if (finalUrl.includes('<iframe')) {
      const match = finalUrl.match(/src="([^"]+)"/);
      if (match) finalUrl = match[1];
    }

    if (finalUrl && !finalUrl.startsWith('http')) {
      setModal({ isOpen: true, title: 'URL ไม่ถูกต้อง', message: 'กรุณากรอกลิงก์ที่ขึ้นต้นด้วย http หรือ https', type: 'error' });
      return;
    }

    localStorage.setItem('google_calendar_url', finalUrl);
    setGoogleCalendarUrl(finalUrl);
    setIsSettingUrl(false);
    setModal({ isOpen: true, title: 'สำเร็จ', message: 'บันทึกการเชื่อมต่อ Google Calendar เรียบร้อยแล้ว', type: 'success' });
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <Modal 
        isOpen={modal.isOpen} 
        onClose={() => setModal({...modal, isOpen: false})} 
        title={modal.title} 
        message={modal.message} 
        type={modal.type} 
      />

      <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
        <div className="bg-white p-1 rounded-2xl border border-gray-100 flex shadow-sm w-full sm:w-auto">
          <button 
            onClick={() => setViewMode('system')}
            className={`flex-1 sm:flex-none px-6 py-2 rounded-xl text-sm font-bold transition-all flex items-center justify-center gap-2 ${
              viewMode === 'system' ? 'bg-indigo-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-50'
            }`}
          >
            <CalendarIcon size={18} />
            ปฏิทินระบบ
          </button>
          <button 
            onClick={() => setViewMode('google')}
            className={`flex-1 sm:flex-none px-6 py-2 rounded-xl text-sm font-bold transition-all flex items-center justify-center gap-2 ${
              viewMode === 'google' ? 'bg-emerald-600 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-50'
            }`}
          >
            <Globe size={18} />
            Google Calendar
          </button>
        </div>

        {viewMode === 'google' && (
          <button 
            onClick={() => setIsSettingUrl(true)}
            className="w-full sm:w-auto flex items-center justify-center gap-2 px-6 py-3 bg-white border border-gray-200 text-gray-600 rounded-2xl font-bold hover:bg-gray-50 transition-all shadow-sm"
          >
            <LinkIcon size={18} />
            ตั้งค่าลิงก์ปฏิทิน
          </button>
        )}
      </div>

      {isSettingUrl && (
        <div className="bg-white p-8 rounded-[2rem] border border-indigo-100 shadow-xl animate-in slide-in-from-top duration-300 space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-xl font-bold text-gray-900 flex items-center gap-2">
              <LinkIcon className="text-indigo-600" /> เชื่อมต่อ Google Calendar
            </h3>
            <button onClick={() => setIsSettingUrl(false)} className="text-gray-400 hover:text-gray-600"><X /></button>
          </div>
          <p className="text-gray-500 text-sm">วางลิงก์ปฏิทินแบบสาธารณะ (Public URL) หรือโค้ดฝัง iFrame ของคุณที่นี่</p>
          <div className="flex flex-col sm:flex-row gap-3">
            <input 
              className="flex-1 px-5 py-4 rounded-2xl bg-gray-50 border border-gray-200 focus:border-indigo-500 outline-none font-mono text-sm"
              placeholder="https://calendar.google.com/..."
              value={urlInput}
              onChange={e => setUrlInput(e.target.value)}
            />
            <button 
              onClick={handleSaveUrl}
              className="px-8 py-4 bg-indigo-600 text-white rounded-2xl font-bold shadow-lg shadow-indigo-100 flex items-center justify-center gap-2"
            >
              <Check size={20} /> ยืนยัน
            </button>
          </div>
        </div>
      )}

      {viewMode === 'system' ? (
        <div className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm overflow-hidden">
          <div className="flex items-center justify-between mb-8">
            <div className="flex flex-col">
              <span className="text-xs font-black text-indigo-500 uppercase tracking-widest">Attendance Records</span>
              <h2 className="text-2xl font-black text-gray-900">{monthNames[currentMonth]} {currentYear + 543}</h2>
            </div>
            <div className="flex gap-2">
              <button onClick={prevMonth} className="p-3 bg-gray-50 text-gray-600 hover:bg-indigo-50 hover:text-indigo-600 rounded-2xl transition-all"><ChevronLeft size={24}/></button>
              <button onClick={nextMonth} className="p-3 bg-gray-50 text-gray-600 hover:bg-indigo-50 hover:text-indigo-600 rounded-2xl transition-all"><ChevronRight size={24}/></button>
            </div>
          </div>

          <div className="grid grid-cols-7 gap-2">
            {['อา', 'จ', 'อ', 'พ', 'พฤ', 'ศ', 'ส'].map((d, i) => (
              <div key={d} className={`text-center text-xs font-black py-4 uppercase tracking-wider ${i === 0 ? 'text-red-400' : i === 6 ? 'text-purple-400' : 'text-gray-400'}`}>{d}</div>
            ))}

            {Array(firstDay).fill(null).map((_, i) => (
              <div key={`empty-${i}`} className="h-24 sm:h-40 bg-gray-50/30 rounded-2xl"></div>
            ))}

            {Array(daysInMonth).fill(null).map((_, i) => {
              const day = i + 1;
              const dateStr = `${currentYear}-${String(currentMonth + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
              const sessions = attendance.filter(a => a.date === dateStr);
              const hasAttendance = sessions.length > 0;

              return (
                <div key={day} className={`h-24 sm:h-40 p-3 border-2 rounded-[1.5rem] transition-all relative group ${
                  hasAttendance ? 'bg-indigo-50/50 border-indigo-100' : 'bg-white border-gray-50 hover:border-gray-200'
                }`}>
                  <span className={`text-sm font-black ${hasAttendance ? 'text-indigo-600' : 'text-gray-300 group-hover:text-gray-900'}`}>{day}</span>
                  {hasAttendance && (
                    <div className="mt-2 space-y-1 overflow-y-auto no-scrollbar max-h-[80%]">
                      {sessions.map(s => (
                        <div key={s.id} className="text-[9px] bg-white border border-indigo-100 text-indigo-600 p-1.5 rounded-lg truncate font-bold shadow-sm">
                          {s.subjectCode}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      ) : (
        <div className="bg-white rounded-[2.5rem] border border-gray-100 shadow-sm overflow-hidden flex flex-col items-center justify-center min-h-[600px]">
          {googleCalendarUrl ? (
            <div className="w-full h-full min-h-[700px] relative">
              <iframe 
                src={googleCalendarUrl} 
                style={{ border: 0 }} 
                width="100%" 
                height="700" 
                frameBorder="0" 
                scrolling="no"
                className="rounded-[2.5rem]"
              ></iframe>
              <div className="absolute top-4 right-4">
                <a 
                  href={googleCalendarUrl} 
                  target="_blank" 
                  rel="noopener noreferrer" 
                  className="bg-white/80 backdrop-blur-md p-3 rounded-2xl shadow-lg border border-white/50 text-indigo-600 hover:bg-white transition-all block"
                >
                  <ExternalLink size={20} />
                </a>
              </div>
            </div>
          ) : (
            <div className="text-center p-12 space-y-6">
              <div className="w-24 h-24 bg-emerald-50 text-emerald-600 rounded-[2rem] flex items-center justify-center mx-auto shadow-sm">
                <Globe size={48} />
              </div>
              <div className="max-w-md mx-auto">
                <h3 className="text-xl font-black text-gray-900 mb-2">ยังไม่ได้ตั้งค่า Google Calendar</h3>
                <p className="text-gray-500 font-medium">คุณสามารถนำลิงก์ปฏิทินที่ตั้งค่าเป็นสาธารณะมาวาง เพื่อดูตารางนัดหมายส่วนตัวหรือตารางสอนได้ในหน้านี้</p>
              </div>
              <button 
                onClick={() => setIsSettingUrl(true)}
                className="bg-emerald-600 text-white px-10 py-4 rounded-2xl font-bold shadow-xl shadow-emerald-100 hover:bg-emerald-700 transition-all"
              >
                ตั้งค่าลิงก์ตอนนี้
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default CalendarView;

import { supabase } from './supabaseClient';
import { Student, Subject, AttendanceSession, SubjectScoreSheet, TelegramConfig } from '../types';

export const storageService = {
  // Students
  getStudents: async (): Promise<Student[]> => {
    const { data, error } = await supabase.from('students').select('*');
    if (error) throw error;
    return data || [];
  },
  saveStudents: async (data: Student[]) => {
    const { error: deleteError } = await supabase.from('students').delete().neq('id', '0');
    if (deleteError) throw deleteError;
    const { error } = await supabase.from('students').insert(data);
    if (error) throw error;
  },

  // Subjects
  getSubjects: async (): Promise<Subject[]> => {
    const { data, error } = await supabase.from('subjects').select('*');
    if (error) throw error;
    return data || [];
  },
  saveSubjects: async (data: Subject[]) => {
    const { error: deleteError } = await supabase.from('subjects').delete().neq('id', '0');
    if (deleteError) throw deleteError;
    const { error } = await supabase.from('subjects').insert(data);
    if (error) throw error;
  },

  // Attendance
  getAttendance: async (): Promise<AttendanceSession[]> => {
    const { data, error } = await supabase.from('attendance').select('*');
    if (error) throw error;
    return data || [];
  },
  saveAttendance: async (data: AttendanceSession[]) => {
    const { error: deleteError } = await supabase.from('attendance').delete().neq('id', '0');
    if (deleteError) throw deleteError;
    const { error } = await supabase.from('attendance').insert(data);
    if (error) throw error;
  },

  // Scores
  getScores: async (): Promise<SubjectScoreSheet[]> => {
    const { data, error } = await supabase.from('scores').select('*');
    if (error) throw error;
    return data || [];
  },
  saveScores: async (data: SubjectScoreSheet[]) => {
    const { error: deleteError } = await supabase.from('scores').delete().neq('subjectCode', 'FORCE_DELETE');
    if (deleteError) throw deleteError;
    const { error } = await supabase.from('scores').insert(data);
    if (error) throw error;
  },

  // Telegram
  getTelegram: async (): Promise<TelegramConfig[]> => {
    const { data, error } = await supabase.from('telegram').select('*');
    if (error) throw error;
    return data || [];
  },
  saveTelegram: async (data: TelegramConfig[]) => {
    const { error: deleteError } = await supabase.from('telegram').delete().neq('subjectCode', 'FORCE_DELETE');
    if (deleteError) throw deleteError;
    const { error } = await supabase.from('telegram').insert(data);
    if (error) throw error;
  },

  // Enrollment
  getEnrollment: async (): Promise<Record<string, string[]>> => {
    const { data, error } = await supabase.from('enrollment').select('*');
    if (error) throw error;
    const result: Record<string, string[]> = {};
    data?.forEach(item => {
      result[item.subjectCode] = item.studentIds;
    });
    return result;
  },
  saveEnrollment: async (data: Record<string, string[]>) => {
    const { error: deleteError } = await supabase.from('enrollment').delete().neq('subjectCode', 'FORCE_DELETE');
    if (deleteError) throw deleteError;
    const payload = Object.entries(data).map(([code, ids]) => ({ subjectCode: code, studentIds: ids }));
    const { error } = await supabase.from('enrollment').insert(payload);
    if (error) throw error;
  },

  // Generic Settings (e.g., Google Calendar URL)
  saveSetting: async (key: string, value: string) => {
    // Attempting to store in local storage first for speed, then could be synced to Supabase if a settings table exists
    localStorage.setItem(key, value);
    try {
      // Logic for supabase settings upsert could go here if table exists
    } catch (e) {
      console.warn("Could not sync setting to Cloud", e);
    }
  },

  getSetting: (key: string): string => {
    return localStorage.getItem(key) || '';
  },

  // Combined Operations
  getAllData: async () => {
    return {
      STUDENTS: await storageService.getStudents(),
      SUBJECTS: await storageService.getSubjects(),
      ATTENDANCE: await storageService.getAttendance(),
      SCORES: await storageService.getScores(),
      TELEGRAM: await storageService.getTelegram(),
      ENROLLMENT: await storageService.getEnrollment()
    };
  },

  restoreAllData: async (data: any) => {
    try {
      if (data.STUDENTS) await storageService.saveStudents(data.STUDENTS);
      if (data.SUBJECTS) await storageService.saveSubjects(data.SUBJECTS);
      if (data.ATTENDANCE) await storageService.saveAttendance(data.ATTENDANCE);
      if (data.SCORES) await storageService.saveScores(data.SCORES);
      if (data.TELEGRAM) await storageService.saveTelegram(data.TELEGRAM);
      if (data.ENROLLMENT) await storageService.saveEnrollment(data.ENROLLMENT);
      return true;
    } catch (e) {
      console.error("Restore failed", e);
      return false;
    }
  },

  clearAllData: async () => {
    await supabase.from('students').delete().neq('id', '0');
    await supabase.from('subjects').delete().neq('id', '0');
    await supabase.from('attendance').delete().neq('id', '0');
    await supabase.from('scores').delete().neq('subjectCode', 'FORCE_DELETE');
    await supabase.from('telegram').delete().neq('subjectCode', 'FORCE_DELETE');
    await supabase.from('enrollment').delete().neq('subjectCode', 'FORCE_DELETE');
  }
};

import React, { useRef, useState } from 'react';
import { Download, Upload, Trash2, ShieldCheck, AlertTriangle, FileJson, RefreshCw, RotateCcw, Database, Copy, Check, Terminal } from 'lucide-react';
import { storageService } from '../services/storageService';
import { initialStudents } from '../initialStudents';
import { initialSubjects } from '../initialSubjects';
import Modal, { ModalType } from './Modal';

const BackupRestore: React.FC = () => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [copied, setCopied] = useState(false);
  const [modal, setModal] = useState<{isOpen: boolean, title: string, message: string, type: ModalType, onConfirm?: () => void}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const showAlert = (title: string, message: string, type: ModalType = 'info', onConfirm?: () => void) => {
    setModal({ isOpen: true, title, message, type, onConfirm });
  };

  const handleExport = async () => {
    try {
      const data = await storageService.getAllData();
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      const date = new Date().toISOString().split('T')[0];
      const time = new Date().toLocaleTimeString('th-TH').replace(/:/g, '-');

      link.href = url;
      link.download = `smartclass_backup_${date}_${time}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
      showAlert('สำเร็จ', 'ดาวน์โหลดไฟล์สำรองข้อมูลเรียบร้อยแล้ว', 'success');
    } catch (e) {
      showAlert('ผิดพลาด', 'ไม่สามารถดึงข้อมูลเพื่อสำรองได้', 'error');
    }
  };

  const handleImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const json = JSON.parse(e.target?.result as string);
        showAlert('ยืนยันการนำเข้า', 'การนำเข้าข้อมูลจะเขียนทับข้อมูลใน Cloud ทั้งหมด ยืนยันที่จะดำเนินการต่อหรือไม่?', 'confirm', async () => {
          const success = await storageService.restoreAllData(json);
          if (success) {
            showAlert('สำเร็จ', 'นำเข้าข้อมูลสำเร็จ! ระบบจะทำการรีโหลดหน้าเว็บ', 'success', () => window.location.reload());
          } else {
            showAlert('ผิดพลาด', 'เกิดข้อผิดพลาดในการเขียนข้อมูลลงฐานข้อมูล', 'error');
          }
        });
      } catch (err) {
        showAlert('ไฟล์ไม่ถูกต้อง', 'กรุณาเลือกไฟล์ JSON ที่ถูกต้อง', 'error');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleClearData = () => {
    showAlert('อันตราย!', 'ข้อมูลทั้งหมดจะถูกลบออกจาก Cloud อย่างถาวร ยืนยันการลบหรือไม่?', 'confirm', async () => {
      await storageService.clearAllData();
      showAlert('สำเร็จ', 'ล้างข้อมูลสำเร็จ!', 'success', () => window.location.reload());
    });
  };

  const handleResetToDefaults = () => {
    showAlert('ยืนยันการรีเซ็ต', 'ระบบจะล้างข้อมูลปัจจุบันและแทนที่ด้วยข้อมูลเริ่มต้น ยืนยันหรือไม่?', 'confirm', async () => {
      await storageService.clearAllData();
      await storageService.saveStudents(initialStudents);
      await storageService.saveSubjects(initialSubjects);
      showAlert('สำเร็จ', 'อัปเดตข้อมูลเป็นค่าเริ่มต้นสำเร็จ!', 'success', () => window.location.reload());
    });
  };

  const sqlSchema = `-- คำสั่ง SQL สำหรับสร้าง Tables ใน Supabase SQL Editor

-- 1. Table Students
CREATE TABLE students (
  id TEXT PRIMARY KEY,
  studentId TEXT,
  fullName TEXT,
  grade TEXT,
  room TEXT,
  number INTEGER
);

-- 2. Table Subjects
CREATE TABLE subjects (
  id TEXT PRIMARY KEY,
  code TEXT,
  name TEXT,
  grade TEXT,
  semester TEXT,
  year TEXT,
  hours INTEGER,
  numCollectScores INTEGER,
  collectPercent INTEGER,
  midtermPercent INTEGER,
  finalPercent INTEGER
);

-- 3. Table Attendance
CREATE TABLE attendance (
  id TEXT PRIMARY KEY,
  subjectCode TEXT,
  date TEXT,
  periods INTEGER,
  records JSONB
);

-- 4. Table Scores
CREATE TABLE scores (
  subjectCode TEXT PRIMARY KEY,
  scores JSONB,
  assignmentNames JSONB
);

-- 5. Table Telegram
CREATE TABLE telegram (
  subjectCode TEXT PRIMARY KEY,
  botName TEXT,
  botToken TEXT,
  chatId TEXT
);

-- 6. Table Enrollment
CREATE TABLE enrollment (
  subjectCode TEXT PRIMARY KEY,
  studentIds JSONB
);`;

  const copySql = () => {
    navigator.clipboard.writeText(sqlSchema);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom duration-500">
      <Modal 
        isOpen={modal.isOpen} 
        onClose={() => setModal({...modal, isOpen: false})} 
        onConfirm={modal.onConfirm}
        title={modal.title} 
        message={modal.message} 
        type={modal.type} 
      />

      <div className="bg-indigo-600 p-8 rounded-[2rem] text-white shadow-xl shadow-indigo-100 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-32 -mt-32 blur-3xl"></div>
        <div className="relative z-10">
          <h2 className="text-2xl font-bold mb-2 flex items-center gap-3">
            <ShieldCheck size={32} />
            จัดการและสำรองข้อมูล Cloud
          </h2>
          <p className="text-indigo-100">ข้อมูลของคุณถูกจัดเก็บอย่างปลอดภัยบน Supabase</p>
        </div>
      </div>

      {/* Database Setup Help */}
      <div className="bg-white p-8 rounded-[2rem] border border-gray-100 shadow-sm space-y-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-amber-50 text-amber-600 rounded-xl flex items-center justify-center shadow-sm">
              <Terminal size={24} />
            </div>
            <div>
              <h3 className="text-xl font-bold text-gray-900">การตั้งค่าฐานข้อมูล (SQL Editor)</h3>
              <p className="text-gray-500 text-sm font-medium">คัดลอกคำสั่งด้านล่างไปวางใน Supabase SQL Editor เพื่อเริ่มใช้งานครั้งแรก</p>
            </div>
          </div>
          <button 
            onClick={copySql}
            className={`p-3 rounded-xl transition-all flex items-center gap-2 font-bold ${
              copied ? 'bg-emerald-50 text-emerald-600' : 'bg-gray-50 text-gray-400 hover:text-indigo-600'
            }`}
          >
            {copied ? <Check size={20} /> : <Copy size={20} />}
            <span className="text-xs">{copied ? 'คัดลอกแล้ว' : 'คัดลอก SQL'}</span>
          </button>
