import React, { useRef, useState } from 'react';
import { Download, Upload, Trash2, ShieldCheck, AlertTriangle, FileJson, RefreshCw, RotateCcw, Database, Copy, Check, Terminal, ExternalLink } from 'lucide-react';
import { storageService } from '../services/storageService';
import { initialStudents } from '../initialStudents';
import { initialSubjects } from '../initialSubjects';
import Modal, { ModalType } from './Modal';

const BackupRestore: React.FC = () => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [copied, setCopied] = useState(false);
  const [modal, setModal] = useState<{isOpen: boolean, title: string, message: string, type: ModalType, onConfirm?: () => void}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const showAlert = (title: string, message: string, type: ModalType = 'info', onConfirm?: () => void) => {
    setModal({ isOpen: true, title, message, type, onConfirm });
  };

  const handleExport = async () => {
    try {
      const data = await storageService.getAllData();
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      const date = new Date().toISOString().split('T')[0];
      const time = new Date().toLocaleTimeString('th-TH').replace(/:/g, '-');

      link.href = url;
      link.download = `smartclass_backup_${date}_${time}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
      showAlert('สำเร็จ', 'ดาวน์โหลดไฟล์สำรองข้อมูลเรียบร้อยแล้ว', 'success');
    } catch (e) {
      showAlert('ผิดพลาด', 'ไม่สามารถดึงข้อมูลเพื่อสำรองได้', 'error');
    }
  };

  const handleImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const json = JSON.parse(e.target?.result as string);
        showAlert('ยืนยันการนำเข้า', 'การนำเข้าข้อมูลจะเขียนทับข้อมูลใน Cloud ทั้งหมด ยืนยันที่จะดำเนินการต่อหรือไม่?', 'confirm', async () => {
          const success = await storageService.restoreAllData(json);
          if (success) {
            showAlert('สำเร็จ', 'นำเข้าข้อมูลสำเร็จ! ระบบจะทำการรีโหลดหน้าเว็บ', 'success', () => window.location.reload());
          } else {
            showAlert('ผิดพลาด', 'เกิดข้อผิดพลาดในการเขียนข้อมูลลงฐานข้อมูล (ตรวจสอบ RLS ใน Supabase)', 'error');
          }
        });
      } catch (err) {
        showAlert('ไฟล์ไม่ถูกต้อง', 'กรุณาเลือกไฟล์ JSON ที่ถูกต้อง', 'error');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleClearData = () => {
    showAlert('อันตราย!', 'ข้อมูลทั้งหมดจะถูกลบออกจาก Cloud อย่างถาวร ยืนยันการลบหรือไม่?', 'confirm', async () => {
      await storageService.clearAllData();
      showAlert('สำเร็จ', 'ล้างข้อมูลสำเร็จ!', 'success', () => window.location.reload());
    });
  };

  const handleResetToDefaults = () => {
    showAlert('ยืนยันการรีเซ็ต', 'ระบบจะล้างข้อมูลปัจจุบันและแทนที่ด้วยข้อมูลเริ่มต้น ยืนยันหรือไม่?', 'confirm', async () => {
      const success = await storageService.restoreAllData({
        STUDENTS: initialStudents,
        SUBJECTS: initialSubjects
      });
      if (success) {
        showAlert('สำเร็จ', 'อัปเดตข้อมูลเป็นค่าเริ่มต้นสำเร็จ!', 'success', () => window.location.reload());
      } else {
        showAlert('ผิดพลาด', 'ไม่สามารถรีเซ็ตข้อมูลได้ (ตรวจสอบสิทธิ์การ Delete ใน Supabase)', 'error');
      }
    });
  };

  // Generate SQL for easy copy-pasting
  const generateFullSql = () => {
    const tableCreation = `-- 1. สร้างตารางทั้งหมด (Tables)
CREATE TABLE IF NOT EXISTS students (id TEXT PRIMARY KEY, studentId TEXT, fullName TEXT, grade TEXT, room TEXT, number INTEGER);
CREATE TABLE IF NOT EXISTS subjects (id TEXT PRIMARY KEY, code TEXT, name TEXT, grade TEXT, semester TEXT, year TEXT, hours INTEGER, numCollectScores INTEGER, collectPercent INTEGER, midtermPercent INTEGER, finalPercent INTEGER);
CREATE TABLE IF NOT EXISTS attendance (id TEXT PRIMARY KEY, subjectCode TEXT, date TEXT, periods INTEGER, records JSONB);
CREATE TABLE IF NOT EXISTS scores (subjectCode TEXT PRIMARY KEY, scores JSONB, assignmentNames JSONB);
CREATE TABLE IF NOT EXISTS telegram (subjectCode TEXT PRIMARY KEY, botName TEXT, botToken TEXT, chatId TEXT);
CREATE TABLE IF NOT EXISTS enrollment (subjectCode TEXT PRIMARY KEY, studentIds JSONB);

-- 2. เปิดสิทธิ์การเข้าใช้งาน (RLS)
ALTER TABLE students DISABLE ROW LEVEL SECURITY;
ALTER TABLE subjects DISABLE ROW LEVEL SECURITY;
ALTER TABLE attendance DISABLE ROW LEVEL SECURITY;
ALTER TABLE scores DISABLE ROW LEVEL SECURITY;
ALTER TABLE telegram DISABLE ROW LEVEL SECURITY;
ALTER TABLE enrollment DISABLE ROW LEVEL SECURITY;

-- 3. ล้างข้อมูลเก่า
TRUNCATE students, subjects, attendance, scores, telegram, enrollment;

-- 4. นำเข้าข้อมูลรายวิชา (Subjects)
INSERT INTO subjects (id, code, name, grade, semester, year, hours, numCollectScores, collectPercent, midtermPercent, finalPercent) VALUES
${initialSubjects.map(s => `('${s.id}', '${s.code}', '${s.name}', '${s.grade}', '${s.semester}', '${s.year}', ${s.hours}, ${s.numCollectScores}, ${s.collectPercent}, ${s.midtermPercent}, ${s.finalPercent})`).join(',\n')};

-- 5. นำเข้าข้อมูลนักเรียน (Students)
INSERT INTO students (id, studentId, fullName, grade, room, number) VALUES
${initialStudents.map(s => `('${s.id}', '${s.studentId}', '${s.fullName}', '${s.grade}', '${s.room}', ${s.number})`).join(',\n')};
`;
    return tableCreation;
  };

  const sqlSchema = generateFullSql();

  const copySql = () => {
    navigator.clipboard.writeText(sqlSchema);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom duration-500 pb-20">
      <Modal 
        isOpen={modal.isOpen} 
        onClose={() => setModal({...modal, isOpen: false})} 
        onConfirm={modal.onConfirm}
        title={modal.title} 
        message={modal.message} 
        type={modal.type} 
      />

      <div className="bg-indigo-600 p-8 rounded-[2rem] text-white shadow-xl shadow-indigo-100 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-32 -mt-32 blur-3xl"></div>
        <div className="relative z-10">
          <h2 className="text-2xl font-bold mb-2 flex items-center gap-3">
            <ShieldCheck size={32} />
            จัดการและสำรองข้อมูล Cloud
          </h2>
          <p className="text-indigo-100">ใช้คำสั่ง SQL เพื่อนำเข้าข้อมูลปริมาณมากได้รวดเร็วที่สุด</p>
        </div>
      </div>

      {/* Database Setup Help */}
      <div className="bg-white p-8 rounded-[2rem] border border-gray-100 shadow-sm space-y-6">
        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-amber-50 text-amber-600 rounded-xl flex items-center justify-center shadow-sm">
              <Terminal size={24} />
            </div>
            <div>
              <h3 className="text-xl font-bold text-gray-900">นำเข้าข้อมูลผ่าน SQL Editor</h3>
              <p className="text-gray-500 text-sm font-medium">รวมคำสั่งสร้างตารางและข้อมูลนักเรียน/วิชาทั้งหมดที่คุณมี</p>
            </div>
          </div>
          <div className="flex gap-2 w-full md:w-auto">
            <button 
              onClick={copySql}
              className={`flex-1 md:flex-none p-3 rounded-xl transition-all flex items-center justify-center gap-2 font-bold ${
                copied ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : 'bg-gray-50 text-gray-400 hover:text-indigo-600 border border-gray-100'
              }`}
            >
              {copied ? <Check size={20} /> : <Copy size={20} />}
              <span>{copied ? 'คัดลอกแล้ว' : 'คัดลอกคำสั่ง SQL ทั้งหมด'}</span>
            </button>
            <a 
              href="https://supabase.com/dashboard" 
              target="_blank" 
              className="p-3 bg-indigo-50 text-indigo-600 border border-indigo-100 rounded-xl hover:bg-indigo-100 transition-all flex items-center gap-2"
            >
              <ExternalLink size={20} />
            </a>
          </div>
        </div>

        <div className="bg-amber-50 p-4 rounded-2xl border border-amber-100 flex gap-3 text-amber-800 text-sm">
          <AlertTriangle className="shrink-0" size={20} />
          <p><b>ข้อแนะนำ:</b> หากนำเข้าผ่านหน้าเว็บแล้วขึ้นข้อผิดพลาด "Error", ให้คัดลอก SQL ด้านล่างนี้ไปรันในเมนู <b>SQL Editor</b> ของ Supabase โดยตรง ระบบจะแก้สิทธิ์การเข้าถึง (Disable RLS) และนำเข้าข้อมูลทั้งหมดให้ทันทีครับ</p>
        </div>

        <div className="relative">
          <pre className="bg-gray-900 text-gray-300 p-6 rounded-2xl text-[10px] md:text-xs overflow-x-auto font-mono h-64 no-scrollbar border border-gray-800">
            {sqlSchema}
          </pre>
          <div className="absolute inset-x-0 bottom-0 h-12 bg-gradient-to-t from-gray-900 to-transparent rounded-b-2xl pointer-events-none"></div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Export Card */}
        <div className="bg-white p-8 rounded-[2rem] border border-gray-100 shadow-sm hover:border-indigo-200 transition-all flex flex-col items-center text-center">
          <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center mb-6">
            <Download size={32} />
          </div>
          <h3 className="text-xl font-bold text-gray-900 mb-2">สำรองข้อมูล (Export)</h3>
          <p className="text-gray-500 mb-8 text-sm leading-relaxed">
            ดาวน์โหลดข้อมูลปัจจุบันจาก Cloud เก็บไว้ในรูปแบบไฟล์ .json
          </p>
          <button 
            onClick={handleExport}
            className="w-full mt-auto bg-blue-600 text-white py-4 rounded-2xl font-bold shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all flex items-center justify-center gap-2"
          >
            <FileJson size={20} />
            ดาวน์โหลดไฟล์สำรอง
          </button>
        </div>

        {/* Import Card */}
        <div className="bg-white p-8 rounded-[2rem] border border-gray-100 shadow-sm hover:border-purple-200 transition-all flex flex-col items-center text-center">
          <div className="w-16 h-16 bg-purple-50 text-purple-600 rounded-2xl flex items-center justify-center mb-6">
            <Upload size={32} />
          </div>
          <h3 className="text-xl font-bold text-gray-900 mb-2">นำเข้าไฟล์ (Restore)</h3>
          <p className="text-gray-500 mb-8 text-sm leading-relaxed">
            กู้คืนข้อมูลจากไฟล์ .json (ระวัง: ข้อมูลเดิมจะถูกลบ)
          </p>
          <input 
            type="file" 
            ref={fileInputRef}
            onChange={handleImport}
            accept=".json"
            className="hidden"
          />
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="w-full mt-auto bg-purple-600 text-white py-4 rounded-2xl font-bold shadow-lg shadow-purple-100 hover:bg-purple-700 transition-all flex items-center justify-center gap-2"
          >
            <RefreshCw size={20} />
            กู้คืนจากไฟล์ .json
          </button>
        </div>
      </div>

      {/* Sync with Defaults */}
      <div className="bg-indigo-50 p-8 rounded-[2rem] border border-indigo-100">
        <div className="flex flex-col md:flex-row items-center justify-between gap-6">
          <div className="flex items-center gap-4 text-center md:text-left">
            <div className="w-12 h-12 bg-white text-indigo-600 rounded-xl flex items-center justify-center shrink-0 shadow-sm border border-indigo-100">
              <RotateCcw size={24} />
            </div>
            <div>
              <h4 className="font-bold text-indigo-900 text-lg">รีเซ็ตเป็นค่าเริ่มต้น</h4>
              <p className="text-indigo-700 text-sm">เขียนทับ Cloud ด้วยรายชื่อนักเรียนและวิชาปี 2568</p>
            </div>
          </div>
          <button 
            onClick={handleResetToDefaults}
            className="bg-white text-indigo-600 border-2 border-indigo-600 px-8 py-4 rounded-2xl font-bold hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center gap-2 shrink-0"
          >
            <RotateCcw size={20} />
            โหลดข้อมูลเริ่มต้นใหม่
          </button>
        </div>
      </div>

      {/* Danger Zone */}
      <div className="bg-red-50 p-8 rounded-[2rem] border border-red-100">
        <div className="flex flex-col md:flex-row items-center justify-between gap-6">
          <div className="flex items-center gap-4 text-center md:text-left">
            <div className="w-12 h-12 bg-red-100 text-red-600 rounded-xl flex items-center justify-center shrink-0">
              <AlertTriangle size={24} />
            </div>
            <div>
              <h4 className="font-bold text-red-900 text-lg">พื้นที่อันตราย</h4>
              <p className="text-red-700 text-sm">ล้างข้อมูลทั้งหมดใน Cloud ถาวร</p>
            </div>
          </div>
          <button 
            onClick={handleClearData}
            className="bg-red-600 text-white px-8 py-4 rounded-2xl font-bold shadow-lg shadow-red-100 hover:bg-red-700 transition-all flex items-center justify-center gap-2 shrink-0"
          >
            <Trash2 size={20} />
            ล้างข้อมูล Cloud ทั้งหมด
          </button>
        </div>
      </div>
    </div>
  );
};

