      } finally {
        setIsResetting(false);
      }
    });
  };

  // Optimized SQL script that handles both table creation and RLS management
  const generateFullSql = () => {
    return `-- 1. สร้างตารางทั้งหมดที่จำเป็น (Tables Setup)
