CREATE TABLE IF NOT EXISTS subjects (id TEXT PRIMARY KEY, code TEXT, name TEXT, grade TEXT, semester TEXT, year TEXT, hours INTEGER, numCollectScores INTEGER, collectPercent INTEGER, midtermPercent INTEGER, finalPercent INTEGER);
CREATE TABLE IF NOT EXISTS attendance (id TEXT PRIMARY KEY, subjectCode TEXT, date TEXT, periods INTEGER, records JSONB);
CREATE TABLE IF NOT EXISTS scores (subjectCode TEXT PRIMARY KEY, scores JSONB, assignmentNames JSONB);
CREATE TABLE IF NOT EXISTS telegram (subjectCode TEXT PRIMARY KEY, botName TEXT, botToken TEXT, chatId TEXT);
CREATE TABLE IF NOT EXISTS enrollment (subjectCode TEXT PRIMARY KEY, studentIds JSONB);

