ALTER TABLE IF EXISTS students DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS subjects DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS attendance DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS scores DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS telegram DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS enrollment DISABLE ROW LEVEL SECURITY;

-- 3. ล้างข้อมูลเก่าเพื่อเตรียมนำเข้าใหม่ (Optional - Clear current data)
TRUNCATE TABLE students, subjects, attendance, scores, telegram, enrollment;

-- 4. คำแนะนำเพิ่มเติม:
-- หลังจากรัน SQL นี้แล้ว ให้กลับไปที่หน้าแอปแล้วกด "โหลดข้อมูลเริ่มต้นใหม่" 
-- เพื่อให้นักเรียนและวิชาปี 2568 ถูกเขียนลงในตารางที่สร้างใหม่นี้ครับ
`;
  };

  const sqlSchema = generateFullSql();

  const copySql = () => {
    navigator.clipboard.writeText(sqlSchema);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom duration-500 pb-20">
      <Modal 
        isOpen={modal.isOpen} 
        onClose={() => setModal({...modal, isOpen: false})} 
